\begin{equation}
\label{eq:problem}
\min_{x\in \mathcal{X}} \max_{y\in\mathcal{Y}} F(x,y).
\tag{P}
\end{equation}

Here, $F:\R^n \times \R^d \rightarrow \R$ can be both nonconvex with respect to $x$ and nonconcave with respect to $y$, $\mathcal{X}\subseteq \R^n$ is a nonempty closed convex set, and $\mathcal{Y}\subseteq \R^d$ is a nonempty compact convex set. This problem has a wide range of applications in machine learning and operations research. Examples include learning with non-decomposable loss~\citep{shalev2016minimizing,zhang2018ell_1}, training generative adversarial networks~\citep{arjovsky2017wasserstein,goodfellow2020generative}, adversarial training~\citep{madry2017towards,sinha2017certifying}, and (distributionally) robust optimization (DRO)~\citep{bertsimas2011theory,rahimian2019distributionally}. 


\begin{assumption}[Problem setup] \label{ass:basic}
The following assumptions on the objective function $F$ of problem \eqref{eq:problem} hold throughout the paper. 
\begin{enumerate}[label=\normalfont(\alph*)]
\item   $(\textrm{\bf Primal function})$ For all $y\in \mathcal{Y}$, the function $F(\cdot,y): \mathbb{R}^n \rightarrow \mathbb{R}$ takes the form $F(\cdot, y):=h_y\circ c_y(\cdot)$, where $c_y:\R^n\rightarrow \R^m$ is 
continuously differentiable
with $L_c$-Lipschitz continuous Jacobian mapping, i.e.,
\[
\|\nabla c_y(x)-\nabla c_y(x')\| \leq L_c\|x-x'\| \quad \text { for all } x, x' \in \mathcal{X};
\]
and $h_y:\R^m\rightarrow \R$  is  convex and $L_h$-Lipschitz continuous, i.e.,
\[
|h_y(z)-h_y(z')| \leq L_h\|z-z'\| \quad \text { for all } z, z' \in \R^{m}.
\]
\item  $(\textrm{\bf Dual function})$ For all $x\in \mathcal{X}$, the function $F(x, \cdot):\R^d \rightarrow \R$ is continuously differentiable  with $\nabla_y F(\cdot,\cdot)$ being $L$-Lipschitz continuous on $\mathcal{X}\times \mathcal{Y}$, i.e., 
\[
\|\nabla_y F(x,y)-\nabla_y F(x',y')\| \leq L\|(x,y)-(x',y')\| \,
\text{ for all }  (x,y), (x',y') \in \mathcal{X}\times\mathcal{Y}.
\]
Without loss of generality, we may take $L=L_h L_c$.
\end{enumerate}
\end{assumption}

\begin{assumption}[K\L{} property with exponent $\theta$ for dual problem]
\label{ass:kl}
For all  $x\in\mathcal{X}$, the problem $\max_{y\in \mathcal{Y}} F(x,y)$ has a nonempty solution set and a finite optimal value. Moreover, there exist $\mu>0$ and $\theta \in [0,1)$ such that  
\[
\dist(0, -\nabla_y F(x,y)+\partial\iota_{\mathcal{Y}}(y)) \ge \mu  \left(\max\limits_{y'\in \mathcal{Y}} F(x,y')-F(x,y)\right)^{\theta}
\]
for all $x \in \mathcal{X}$ and  $y \in \mathcal{Y}\setminus \mathcal{Y}^\star(x)$, where $\mathcal{Y}^\star(x):= \argmax_{y' \in \mathcal{Y}} F(x,y')$ 
% satisfying $F(x,y)<\max_{y'\in\mathcal{Y}} F(x,y')$
.
\end{assumption}

Let us now examine the stationarity measures discussed in this paper. We define the value function $f:\mathbb{R}^n \rightarrow \mathbb{R}$, the potential function $F_r:\R^n\times \R^d\times \R^n\rightarrow\R$, and the dual potential value function $d_r:\R^d\times \R^n\rightarrow \R$ by
% \[
% F_r(x,y,z) := F(x,y)+\frac{r}{2}\|x-z\|^2\quad \text{and}\quad d_r(y,z):=\min_{x\in\mathcal{X}} F_r(x,y,z),
% \]
\begin{align*}
f(x) := \max_{y \in \mathcal{Y}} F(x,y),\quad F_r(x,y,z) := F(x,y) + \frac{r}{2} \| x-z \|^2,\quad d_r(y,z) := \min_{x \in \mathcal{X}} F_r(x,y,z),
\end{align*}
respectively, where we assume $r> L$ in the rest of this paper.


\begin{definition}[Stationarity measures]
\label{defi:primal-dual}
Let $\epsilon \ge 0$ be given.
\begin{enumerate}[label=\normalfont(\alph*)]
\item The point $x\in\mathcal{X}$ is an $\epsilon$-optimization-stationary point {\rm($\epsilon$-OS)} of problem \eqref{eq:problem} if 
\[\|\prox_{\frac{1}{r}f+\iota_{\mathcal{X}}}(x)-x\|\leq \epsilon.\]
\item The pair $(x, y)\in\mathcal{X}\times \mathcal{Y}$ is an $\epsilon$-game-stationary point {\rm ($\epsilon$-GS)} of problem \eqref{eq:problem} if 
% there exists a pair $(u, v)$ such that
\[
\|\nabla_{z} d_r(y,x)\|\leq\epsilon \quad \text{and} \quad {\rm dist}(0,-\nabla_{y} F(x, y)+\partial\iota_{\mathcal{Y}}(y))\leq\epsilon. \footnote{For any $x \in \mathbb{R}^{\ell}$ and $\mathcal{S} \subseteq \mathbb{R}^{\ell}$, we use $\dist(x, \mathcal{S}):=\inf\limits_{z\in\mathcal{S}}\|x-z\|$ to denote the distance from $x$ to $\mathcal{S}$.} 
% \quad \text { and } \quad\|u\|,\|v\| \leq \epsilon.
\]
\end{enumerate}
% where $1_{\mathcal{Y}}$ is the indicator function of the set $\mathcal{Y}$. 
% A pair $(x, y)$ is a stationary solution if $\mu = 0, \nu = 0$. 
\end{definition}

\begin{equation}
    \label{eq:primal_update}
    x^{k+1} \in \mathop{\argmin}_{x\in\mathcal{X}} \left\{ F_{x^k,\lambda}(x,y^k)
  +\frac{r}{2}\|x-z^{k}\|^2
    \right\},
\end{equation}

\[
F_{x^k,\lambda}(x,y^k):=h_{y^k}\left(c_{y^k}(x^{k})+\nabla c_{y^k}(x^{k})^\top(x-x^{k})\right)+\frac{1}{2\lambda}\|x-x^k\|^2.
\]

\begin{algorithm}[H]\label{alg}
    \caption{\textbf{Smoothed PLDA}}
    \SetKwInOut{Input}{Input}
    \Input{Initial point $(x^0,y^0,z^0)$ and parameters $r>L$, $\lambda> 0$, $\alpha>0$, $\beta\in(0,1)$}
    \For{$k=0,1,2,\ldots$}{
    $x^{k+1}:= \mathop{\argmin}\limits_{x \in \mathcal{X}} \left\{F_{x^k,\lambda}(x,y^k) + \frac{r}{2}\|x-z^k\|^2\right\}$\\
    $y^{k+1}:=\proj_{\mathcal{Y}}\left(y^k+\alpha \nabla_{y} F(x^{k+1}, y^k)\right)$ \\
    $z^{k+1}:=z^k+\beta(x^{k+1}-z^k)$}
\end{algorithm}

We emphasize that the optimal approach to solving \eqref{eq:primal_update} depends on the problem's specific structure. For simplicity and to focus on our main contributions, we assume the exactness of the primal update and concentrate on the iteration complexity of the outer loop in subsequent analyses.


