\|x_r(y(z^{k+1}), z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\| \leq \omega \|y^{k}-y_{+}^{k}(z^{k+1})\|^\upsilon
\end{equation}

for some constants $\omega>0$ and $\upsilon>0$. 


\begin{definition}[Weak convexity]
\label{defi:weak-convex}
 A function $\ell:\R^n \rightarrow \R$ is said to be $\rho$-weakly convex on a set $\mathcal{X}\subseteq \R^n$ for some constant $\rho \ge 0$ if for any $x, y \in \mathcal{X}$ and $\tau \in [0,1]$, we have
$$
\ell(\tau x+(1-\tau) y) \leq \tau \ell(x)+(1-\tau) \ell(y)+\frac{\rho \tau(1-\tau)}{2}\|x-y\|^{2}.
$$
% When $\ell$ is locally Lipschitz, 
The above definition is equivalent to the convexity of the function $\ell(\cdot) + \tfrac{\rho}{2} \| \cdot \|^2$ on $\mathcal{X}$.
\end{definition}

\begin{definition}[Proximal mapping]
% Consider a $\rho$-weakly convex function 
Let $\ell:\R^n\rightarrow \R \cup \{+\infty\}$ 
% and fix a parameter $\mu < \rho^{-1}$
be a proper lower-semicontinuous function.  The proximal mapping of $\ell$ with parameter $\mu>0$ at the point $x \in \mathbb{R}^n$ is defined by
\[
\prox_{\mu \ell}(x) = \mathop{\argmin}_{y\in \R^n} \left\{ \ell(y) + \frac{1}{2\mu} \|y-x\|^2\right\}. 
\]
\label{defi:prox}
\end{definition}

Using Definition \ref{defi:weak-convex} and Fact \ref{fact-1}, we can deduce that $F_r(\cdot,y,z)$ is $(r-L)$-strongly convex for any $y \in \mathcal{Y}$ and $z \in \mathbb{R}^n$.


The following lemma provides a dual error bound for the case where $F(x,\cdot)$ is concave for any $x \in \mathbb{R}^n$. Its proof is based on  Lemma B.10 in \citep{zhang2020single}.

