\begin{proposition}[Basic descent estimate of $\Phi_r$]
\label{prop:decrease}
    Let 
    % $r\ge3L$, $\lambda\le \frac{1}{L}$, $\alpha \leq \min\left\{\frac{1}{10L}, \frac{1}{4L\zeta^2} \right\}$, and $\beta  \leq \min \left\{\frac{1}{28}, \frac{(r-L)^2}{14\alpha r(2r-L)^2}\right\}$,     
    \[r\ge3L,\ \lambda\le \frac{1}{L},\ \alpha \leq \min\left\{\frac{1}{10L},\ \frac{1}{4L\zeta^2} \right\},\ \beta  \leq \min \left\{\frac{1}{28},\ \frac{(r-L)^2}{14\alpha r(2r-L)^2}\right\},\] 
    where $\zeta>0$ is the constant defined in Proposition \ref{prop:lip}.
    Then, for any $k\ge0$, we have
\begin{equation*}
\begin{aligned}
\Phi_r^k-\Phi_r^{k+1}\ge\ &  \frac{3}{8\lambda}\|x^{k}-x^{k+1}\|^{2}+\frac{1}{8\alpha}\|y^{k}-y_{+}^{k}(z^{k+1})\|^2 +\frac{4r}{7\beta}\|z^{k}-z^{k+1}\|^{2} \\
& - 14r\beta\|x_r(y(z^{k+1}), z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|^{2},
\end{aligned}
\end{equation*}
where $\Phi_r^k:= \Phi_r(x^k,y^k,z^k)$. 
% \footnote{The proof of Proposition \ref{prop:decrease}, which is based on the primal descent, dual ascent, and proximal descent properties, is given in Appendix \ref{sec:suff_decrease}. }
\end{proposition}

\begin{proposition} [Lipschitz-type primal error bound]
\label{prop:lip}
%  Suppose that $r-L > 0$. Then 
 For any $k\ge0$, we have
    \begin{equation}\label{iter-result1}
        \|x^{k+1}-x_r(y^{k}, z^{k})\| \leq \zeta\|x^{k}-x^{k+1}\|,
        \end{equation}
where   $\zeta: =\frac{2(r-L)^{-1}+(\lambda^{-1}+L) ^{-1}}{(\lambda^{-1}+L) ^{-1}} \left(\sqrt{\frac{2L}{\lambda^{-1}+L}}+1\right)$.
% and $\eta:=\alpha L \zeta$. 
\end{proposition}

\begin{proof}
For ease of notation, we define $\hat{F}_{y,z}(\cdot): = F_r(\cdot,y,z) + \iota_{\mathcal{X}}(\cdot)$ for any $y\in\mathcal{Y}$ and $z\in\R^n$.  As $x_r(y,z)$ is the optimal solution of $\min_{x \in \mathbb{R}^n} \hat{F}_{y,z} (x)$ and $F_r(\cdot,y,z)$ is $(r-L)$-strongly convex (see the remark after Fact \ref{fact-2} in Appendix \ref{sec:lemmas}), we have
\begin{equation}
    \label{eq:lip_1} 
    \hat{F}_{y^k,z^k}(x)-\hat{F}_{y^k,z^k}(x_r(y^k,z^k)) \ge \frac{r-L}{2} \|x-x_r(y^k,z^k)\|^2 \quad \text{for all}\ x \in \mathcal{X}.
\end{equation}
In addition, by the convexity of $\hat{F}_{y^k,z^k}$, we obtain 
\begin{equation}
    \label{eq:lip_2}
    \begin{aligned}
    \hat{F}_{y^k,z^k}(x)-\hat{F}_{y^k,z^k}(x_r(y^k,z^k)) & \leq \dist(0, \partial \hat{F}_{y^k,z^k}(x))\cdot \|x-x_r(y^k,z^k)\| \\ 
    \end{aligned}
\end{equation}
$\text{for all}\ x\in\mathcal{X}$.
Combining \eqref{eq:lip_1} and \eqref{eq:lip_2} yields
\[
\|x-x_r(y^k,z^k)\| \leq \frac{2}{r-L} \dist(0, \partial \hat{F}_{y^k,z^k}(x)) \quad \text{for all}\ x\in\mathcal{X}. 
\]
By utilizing the equivalence between proximal and subdifferential error bounds \citep[Theorem 3.4]{drusvyatskiy2018error}, we  conclude that
\begin{equation}
\label{eq:;lip_3}
    \|x-x_r(y^k,z^k)\|  \leq \frac{2(r-L)^{-1}+t}{t} \left\|x - \prox_{t  \hat{F}_{y^k,z^k}}(x)\right\| \text{ for all } t>0, \, x\in\mathcal{X}.
\end{equation}
Now, let us examine the relationship between  $\|x^{k+1}-x^k\|$ and $\|x^{k+1} - \prox_{t \hat{F}_{y^k,z^k}}(x^{k+1})\|$. Let $\varphi_k:\R^n\rightarrow \R \cup \{+\infty\}$ be the function defined by
\[
\varphi_k(x):=\hat{F}_{y^k,z^k}(x)+\frac{\lambda^{-1}+L}{2}\|x-x^k\|^{2}-\frac{\lambda^{-1} + L}{2}\|x-x^{k+1}\|^{2}.
\]
% By combining Fact \ref{fact-2} and the strong convexity of $F_{x^k,\lambda}(\cdot,y^k)$
It is clear that for any $x\in\mathcal{X}$,
\begin{align*}\label{safeguard-key1}
            & \hat{F}_{y^k,z^k}(x)
             = F(x,y^k) + \frac{r}{2}\|x-z^k\|^2 \notag\\
             \ge\ & F_{x^k,\lambda}(x,y^k) -\frac{\lambda^{-1}+L}{2}\|x-x^{k}\|^2 + \frac{r}{2}\|x-z^k\|^2\notag \\ 
              \ge\ &  F_{x^k,\lambda}(x^{k+1},y^k) +\frac{\lambda^{-1}+r}{2}\|x-x^{k+1}\|^2 -\frac{\lambda^{-1}+L}{2}\|x-x^{k}\|^2 +\frac{r}{2}\|x^{k+1}-z^k\|^2\notag\\
             \ge\ & F(x^{k+1},y^k) + \frac{\lambda^{-1}-L}{2}\|x^{k}-x^{k+1}\|^2 +\frac{\lambda^{-1}+r}{2}\|x-x^{k+1}\|^2\ \\
             & \ -\frac{\lambda^{-1}+L}{2}\|x-x^{k}\|^2 + \frac{r}{2}\|x^{k+1}-z^k\|^2 \notag \\ 
             =\ & \hat{F}_{y^k,z^k}(x^{k+1})+\frac{\lambda^{-1}-L}{2}\|x^{k+1}-x^k\|^2 +\frac{\lambda^{-1}+r}{2}\|x-x^{k+1}\|^2 -\frac{\lambda^{-1}+L}{2}\|x-x^{k}\|^2,
\end{align*}
where the first and third inequalities follow from Fact \ref{fact-2}, and the second one is from the $(\lambda^{-1} + r)$-strong convexity of $F_{x^k,\lambda}(\cdot,y^k) +\frac{r}{2}\|\cdot-z^k\|^2$ on $\mathcal{X}$ and the definition of $x^{k+1}$.
Since $r > L$, we see that for any $x\in\mathcal{X}$,
\begin{align*}
\varphi_k(x)
&\ge \hat{F}_{y^k,z^k}(x^{k+1})+\frac{\lambda^{-1}-L}{2}\|x^{k+1}-x^{k}\|^2+\frac{r-L}{2}\|x-x^{k+1}\|^2\notag\\
&\ge\hat{F}_{y^k,z^k}(x^{k+1})+\frac{\lambda^{-1}-L}{2}\|x^{k+1}-x^{k}\|^2.
\end{align*}
It then follows from the definition of $\varphi_k$ that 
\[\varphi_k(x^{k+1})-\inf_{x\in\R^n} \varphi_k(x)\leq L \|x^{k+1}-x^k\|^2.\]
This, together with the definition of the proximal mapping, implies that for any $\rho>0$,
\begin{align}
&\varphi_k\left(\operatorname{prox}_{\frac{1}{\rho} \varphi_k}(x^{k+1})\right)+\frac{\rho}{2}\|\operatorname{prox}_{\frac{1}{\rho} \varphi_k}(x^{k+1})-x^{k+1}\|^{2}\leq  \varphi_k(x^{k+1})\notag\\
\leq\ & \inf_{x\in\R^n} \varphi_k(x)+L \|x^{k+1}-x^k\|^2
\leq \varphi_k\left(\operatorname{prox}_{\frac{1}{\rho} \varphi_k}(x^{k+1})\right)+L \|x^{k+1}-x^k\|^2,\notag
\end{align}
which in turn implies that
\begin{equation}\label{safeguard-key111}
\|\operatorname{prox}_{\frac{1}{\rho} \varphi_k}(x^{k+1})-x^{k+1}\|\leq \sqrt{\frac{2L}{\rho}} \|x^{k+1}-x^k\|.    
\end{equation}
Recall that our goal is to find a relationship between  $\|x^{k+1}-x^k\|$ and $\|x^{k+1} - \prox_{t \hat{F}_{y^k,z^k}}(x^{k+1})\|$. To do this, it suffices to relate $\prox_{t \hat{F}_{y^k,z^k}}(x^{k+1})$ to $\operatorname{prox}_{\frac{1}{\rho} \varphi_k}(x^{k+1})$.  By definition, we have
\[\hat{F}_{y^k,z^k}(x)+\frac{\lambda^{-1}+L}{2}\|x-x^{k}\|^{2}=\varphi_k(x)+\frac{\lambda^{-1}+L}{2}\|x-x^{k+1}\|^{2},\]
which implies that $\operatorname{prox}_{\frac{1}{\lambda^{-1}+L} \varphi_k}(x^{k+1})=\operatorname{prox}_{\frac{1 }{\lambda^{-1}+L}\hat{F}_{y^k,z^k}}(x^k)$. 
By setting $t = (\lambda^{-1} + L)^{-1}$ in \eqref{eq:;lip_3} and $\rho = \lambda^{-1} + L$ in \eqref{safeguard-key111}, we conclude that
\begin{align*}
    &\|x^{k+1}-x_r(y^{k}, z^{k})\| \notag\\
    \leq\ & \frac{2(r-L)^{-1}+(\lambda^{-1}+L) ^{-1}}{(\lambda^{-1}+L) ^{-1}}\left\|x^{k+1}- \prox_{\frac{1}{\lambda^{-1}+L} \hat{F}_{y^k,z^k}}(x^{k+1})\right\| \\
    \leq\ &   \frac{2(r-L)^{-1}+(\lambda^{-1}+L) ^{-1}}{(\lambda^{-1}+L) ^{-1}}\left(\left\|x^{k+1}- \prox_{\frac{1}{\lambda^{-1}+L} \hat{F}_{y^k,z^k}}(x^{k})\right\|+ \|x^{k+1}-x^k\|\right) \\
     =\ &   \frac{2(r-L)^{-1}+(\lambda^{-1}+L) ^{-1}}{(\lambda^{-1}+L) ^{-1}}\left(\left\|x^{k+1}- \prox_{\frac{1}{\lambda^{-1}+L} \varphi_k}(x^{k+1})\right\|+ \|x^{k+1}-x^k\|\right) \\
    \leq\ & \frac{2(r-L)^{-1}+(\lambda^{-1}+L) ^{-1}}{(\lambda^{-1}+L) ^{-1}} \left(\sqrt{\frac{2L}{\lambda^{-1}+L}}+1\right) \|x^{k+1}-x^k\|,
\end{align*}
where the second inequality is due to the nonexpansiveness of the proximal mapping. The proof is complete.
\end{proof}

\begin{proposition}[Dual error bound with K\L{} exponent] 
\label{prop:dual_eb_KL}
% Let $\delta>0$. 
Suppose that Assumption \ref{ass:kl} holds. Then, for any $y\in\mathcal{Y}$ and $z \in \mathbb{R}^n$, we have
% \[
% \|x_r^\star(z)-x_r(y_+(z),z)\| \leq \omega \|y-y_+(z)\|^{\frac{1}{2\theta}},
% \]
% where $\omega:=\frac{\sqrt{2}}{\sqrt{r-L}}\left(\frac{1+\alpha L(1+\sigma_2)}{\alpha\mu}\right)^{\frac{1}{2\theta}}$.
\begin{enumerate}[label=\normalfont(\alph*)]
 \item \rm{(K\L\ exponent $\theta=0$):} $\|x_r(y(z),z)-x_r(y_+(z),z)\| \leq \omega_1 \|y-y_+(z)\|$, 
  \item \rm{(K\L\ exponent $\theta\in(0,1)$):} $\|x_r(y(z),z)-x_r(y_+(z),z)\| \leq \omega_2\|y-y_+(z)\|^{\frac{1}{2\theta}}$, 
  \end{enumerate}
    where $\omega_1:= \frac{\sqrt{2L\cdot {\rm diam}(\mathcal{Y})}\cdot (1+\alpha L)}{\alpha\mu\sqrt{r-L}}$ and $\omega_2:=\frac{\sqrt{2}}{\sqrt{r-L}}\left(\frac{1+\alpha L(1+\sigma_2)}{\alpha\mu}\right)^{\frac{1}{2\theta}}$ (recall that $y_+(z) = \proj_{\mathcal{Y}} ( y + \alpha \nabla_y F(x_r(y,z), y)$).  
\end{proposition}

\begin{proof}
Let $\psi:\R^n\times \R^n\rightarrow\R$ be the function defined by
\[
\psi(x,z) =  F_r(x,y(z),z). 
\]
Consider arbitrary $x \in \mathcal{X}$, $y \in \mathcal{Y}$, and $z \in \mathbb{R}^n$. Note that the function $\psi(\cdot,z)$ is $(r-L)$-strongly convex. Since
\begin{align*}
\mathop{\argmin}_{x'\in\mathcal{X}}\psi(x',z) & =\mathop{\argmin}_{x'\in\mathcal{X}} F_r(x',y(z),z) =  x_r(y(z),z),
\end{align*}
we see that 
% for any $x\in \mathcal{X}$, 
\begin{equation}
\label{eq:dual1}
\psi(x,z) - \psi(x_r(y(z),z),z) \ge \frac{r-L}{2}\|x-x_r(y(z),z)\|^2. 
\end{equation}
In addition, we have
\begin{align} 
\label{eq:dual2}
&\psi(x,z) - \psi(x_r(y(z),z),z)\notag\\   
\leq \  &\psi(x,z)-F_r(x_r(y_+(z),z),y_+(z),z)\notag \\
\leq \ & \max_{y^\prime\in \mathcal{Y}} F(x,y^\prime) + \frac{r}{2}\|x-z\|^2-F_r(x_r(y_+(z),z),y_+(z),z)\notag\\
=\,& \max_{y^\prime\in \mathcal{Y}}F(x,y^\prime)-F(x_r(y_+(z),z),y_+(z)) + \frac{r}{2}\|x-z\|^2-\frac{r}{2}\|x_r(y_+(z),z)-z\|^2,
\end{align}
where the first inequality follows from
\begin{align*}
F_r(x_r(y_+(z),z),y_+(z),z) 
=\ & \min_{x'\in\mathcal{X}}\left\{ F(x',y_+(z)) +\frac{r}{2}\|x'-z\|^2\right\} \nonumber \\
\leq\ & \max_{y' \in \mathcal{Y}}\min_{x'\in\mathcal{X}}\left\{F(x',y') +\frac{r}{2}\|x'-z\|^2\right\} \nonumber \\
=\ & \min_{x'\in\mathcal{X}}\left\{F(x',y(z)) +\frac{r}{2}\|x'-z\|^2\right\} \nonumber \\
=\ & \min_{x'\in\mathcal{X}} \psi(x',z)
= \psi(x_r(y(z),z),z). % \label{eq:Fr-one}
\end{align*}
% \Jiajin{We may have to double-check the above derivation. --- confirmed. With the uniform KL property, we can confirm  $x(y(z),z)$ is unique over $Y(z)$.}
As \eqref{eq:dual1} and \eqref{eq:dual2} hold for any $x\in\mathcal{X}$, we obtain the intermediate relation
\begin{equation}\label{OS-GS-better-key3-main} 
% \begin{aligned}
     \frac{r-L}{2}\|x_r(y(z),z)-x_r(y_+(z),z)\|^2\leq  \max\limits_{y^\prime\in \mathcal{Y}} F(x_r(y_+(z),z),y^\prime) - F(x_r(y_+(z),z),y_+(z)) 
% \end{aligned}
\end{equation}
by taking $x= x_r(y_+(z),z)$.

Now, we utilize the K{\L} exponent $\theta$ of the dual problem to bound the right-hand side of 
\eqref{OS-GS-better-key3-main}  in terms of $\|y-y_+(z)\|$. Consider the following two cases:
 \begin{enumerate}[label=\normalfont(\alph*)]
 \item Suppose that $\theta=0$. If $F(x_r(y_+(z),z),y_+(z))=\max_{y'\in\mathcal{Y}} F(x_r(y_+(z),z),y')$, then the desired inequality follows trivially from~\eqref{OS-GS-better-key3-main}. Otherwise, we have $y_+(z) \in \mathcal{Y} \setminus \mathcal{Y}^\star(x_r(y_+(z),z))$. By Assumption~\ref{ass:kl}, we have
% we deduce using~\eqref{eq:Fr-one} that
% \begin{align*}
% F_r(x_r(y_+(z),z),y_+(z),z)
% &=\max_{y'\in\mathcal{Y}} F_r(x_r(y_+(z),z),y',z)\\
% &\ge F_r(x_r(y_+(z),z),y_+(z),z)\\
% &\ge F_r(x_r(y(z),z),y(z),z).
% \end{align*}
%By definition of $y(z)$, it follows that $y_+(z)=y(z)$, and consequently the conclusion trivially holds. 
\[
\dist(0, -\nabla_y F(x_r(y_+(z),z),y_+(z))+\partial\iota_{\mathcal{Y}}(y_+(z)))\ge \mu.
\]
Since  $F(x,\cdot)$ is continuously differentiable on the compact set $\mathcal{Y}$, $\|\nabla_y F(x,\cdot)\|$ is bounded on $\mathcal{Y}$. Without loss of generality, we can assume that  $\|\nabla_y F(x,\cdot)\|\leq L$ on $\mathcal{Y}$. According to  the mean value theorem, we have 
\[
\max\limits_{y^\prime\in \mathcal{Y}} F(x_r(y_+(z),z),y^\prime) - F(x_r(y_+(z),z),y_+(z))
\leq L \cdot {\rm diam}(\mathcal{Y}).
\]
Using the fact that $y_+(z) = \proj_{\mathcal{Y}} (y + \alpha \nabla_y F(x_r(y,z), y))$, we bound
\begin{align*}
 &\max\limits_{y^\prime\in \mathcal{Y}} F(x_r(y_+(z),z),y^\prime) - F(x_r(y_+(z),z),y_+(z))\notag\\
\leq\ & \frac{L \cdot {\rm diam}(\mathcal{Y})}{\mu^2}\cdot\dist^2(0, -\nabla_y F(x_r(y_+(z),z),y_+(z))+\partial\iota_{\mathcal{Y}}(y_+(z)))\notag\\ 
% \stackrel{\text{\ding{172}}}{\leq} \ &   \frac{L \cdot {\rm diam}(\mathcal{Y})}{\mu^2} b^2 \|\proj_{\mathcal{Y}}(y+\alpha\nabla_y F(x_r(y_+(z),z),y))-y\|^2
% \notag \\
% \leq \ &  \frac{ L b^2 \cdot {\rm diam}(\mathcal{Y})}{\mu^2}(
% \|\proj_{\mathcal{Y}}(y+\alpha\nabla_y F(x_r(y_+(z),z),y))-y_+(z)\|\ +\|y_+(z)-y\|)^2 \\ 
% \leq \ & \frac{L b^2 \cdot {\rm diam}(\mathcal{Y})}{\mu^2}(\alpha L \|x_r(y_+(z),z)-x_r(y,z)\| + \|y-y_+(z)\|)^2\\
\leq \ & \frac{L b^2 \cdot {\rm diam}(\mathcal{Y})}{\mu^2}\|y_+(z)-y\|^2,
\end{align*}
where $b:=\frac{1}{\alpha} + L > 0$ and the last inequality is due to the fact that the projected gradient ascent method satisfies the so-called \textit{relative error condition}
\citep[Section 5]{attouch2013convergence}. 
It follows that
\[
\|x_r(y(z),z)-x_r(y_+(z),z)\| \leq\frac{\sqrt{2L\cdot {\rm diam}(\mathcal{Y})}\cdot (1+\alpha L)}{\alpha\mu\sqrt{r-L}}\|y-y_+(z)\|. 
\]
\item If $\theta \in (0,1)$, then we have
\begin{align*}
% \label{KL-key-01}
& \mu\left(\max\limits_{y^\prime\in \mathcal{Y}} F(x_r(y_+(z),z),y^\prime) - F(x_r(y_+(z),z),y_+(z))\right)^{\theta}\notag\\
\leq \ & \dist(0, -\nabla_y F(x_r(y_+(z),z),y_+(z))+\partial\iota_{\mathcal{Y}}(y_+(z))) \notag\\ 
\leq \ & \dist(0, -\nabla_y F(x_r(y,z),y_+(z)) +\partial\iota_{\mathcal{Y}}(y_+(z)))   \notag\\
\ & + \|\nabla_y F(x_r(y,z),y_+(z))-\nabla_y F(x_r(y_+(z),z),y_+(z))\|\notag\\ 
{\leq} \ & \dist(0, -\nabla_y F(x_r(y,z),y_+(z))+\partial\iota_{\mathcal{Y}}(y_+(z)))+ L\sigma_2\|y-y_+(z)\|\notag\\
{\leq} \ & \left(\frac{1}{\alpha}+L+L\sigma_2\right)\|y_+(z)-y\|,
\end{align*}
where the third inequality follows from the $L$-Lipschitz continuity  of $\nabla_y F(\cdot,\cdot)$ and  \eqref{lip-y};  the last inequality follows from the relative error condition of the projected gradient ascent method. This, together with \eqref{OS-GS-better-key3-main}, yields
\[
\|x_r(y(z),z)-x_r(y_+(z),z)\|\leq \frac{\sqrt{2}}{\sqrt{r-L}}\left(\frac{1+\alpha L(1+\sigma_2)}{\alpha\mu}\right)^{\frac{1}{2\theta}} 
\|y-y_+(z)\|^{\frac{1}{2\theta}}.
\]
 \end{enumerate}
The proof is complete.
\end{proof}

\begin{corollary}[Alternative dual error bound with K\L{} exponent]
% Let $\delta>0$. 
Suppose that  Assumption \ref{ass:kl} holds. Then, for any $y \in \mathcal{Y}$ and $z \in \mathbb{R}^n$,  we have
% \[
% \|x_r^\star(z)-x_r(y_+(z),z)\| \leq \omega \|y-y_+(z)\|^{\frac{1}{2\theta}},
% \]
% where $\omega:=\frac{\sqrt{2}}{\sqrt{r-L}}\left(\frac{1+\alpha L(1+\sigma_2)}{\alpha\mu}\right)^{\frac{1}{2\theta}}$.
\begin{enumerate}[label=\normalfont(\alph*)]
 \item \rm{(K\L\ exponent $\theta=0$):} $\|x_r^\star(z)-x_r(y_+(z),z)\| \leq \omega_1 \|y-y_+(z)\|$,
  \item \rm{(K\L\ exponent $\theta\in(0,1)$):} $\|x_r^\star(z)-x_r(y_+(z),z)\| \leq \omega_2\|y-y_+(z)\|^{\frac{1}{2\theta}}$. 
  \end{enumerate}
 \label{prop:dual_eb_KL2}   
\end{corollary}

\begin{lemma} \label{lemma-episolcol}
        Let $\epsilon\ge 0$ be given. Suppose that
        \[
        \max\left\{\|x^{k+1}-x^{k}\|,\|y^{k}_+(z^{k+1}) - y^k\|,\|x^{k+1}-z^k\|\right\} \leq  \epsilon.
        \]
        Then,  $\left(x^{k+1}, y^{k+1}\right)$ is a $\rho \epsilon$-GS of problem \eqref{eq:problem}, where
\[\rho = \max\left\{(\eta+1+\sigma_1\alpha\beta L)\left(\frac{1}{\alpha}+L\right), r(\zeta+\sigma_2(\eta+1+\sigma_1\alpha \beta L)+\sigma_1)\right\}\] 
 with $\sigma_{1}:=\frac{r}{r-L}$ and $\sigma_{2}:=\frac{2r-L}{r-L}$.
        \end{lemma}

\begin{proof}
By Definition \ref{defi:primal-dual}, we only have to quantify $\|\nabla_{z} d_r(y^{k+1},x^{k+1})\|$ and ${\rm dist}(0,-\nabla_{y} F(x^{k+1}, y^{k+1})+\partial\iota_{\mathcal{Y}}(y^{k+1}))$.
To begin, observe that
\begin{equation*}
\begin{aligned}
& \| \nabla_{z} d_r(y^{k+1},x^{k+1})\| 
\\
=\ & r \|x^{k+1}-x_r (y^{k+1},x^{k+1})\|\\  
\leq\ & r(\|x^{k+1}-x_r(y^{k},z^{k})\| +\|x_r(y^{k},z^{k})-x_r(y^{k+1},z^{k})\|)  +r \|x_r(y^{k+1},z^{k})-x_r(y^{k+1},x^{k+1})\|  \\
\leq\  &  r\left(\zeta\|x^{k+1}-x^k\| +\sigma_2\|y^{k}-y^{k+1}\| + \sigma_1 \|x^{k+1}-z^{k}\| \right) \\
% \leq & r\left(\|x^{k+1}-x_r(y^{k},z^{k})\| +\|x_r(y^{k},z^{k})-x_r(y^{k+1},z^{k})\| + \|x_r(y^{k+1},z^{k})-x_r(y^{k+1},x^{k+1})\| \right) \\
\leq\  &  r\left(\zeta\|x^{k+1}-x^k\| + \sigma_1 \|x^{k+1}-z^{k}\| \right) +r\sigma_2 (\eta\| x^{k+1}-x^k\|+\sigma_1\alpha L\|z^{k+1}-z^k\|+\| y_+^k(z^{k+1})-y^k\|)\\
\leq\ & r(\zeta+\sigma_2(\eta+1+\sigma_1\alpha \beta L)+\sigma_1)\epsilon,
\end{aligned}
\end{equation*}
where the second inequality is due to Proposition \ref{prop:lip} and Lemma \ref{lemma-sollip}, the third is due to Lemma \ref{lemma-dualxy}, and the fourth follows from the update $z^{k+1} = z^k + \beta (x^{k+1} - x^k)$ and the assumption of the lemma. Next, recall that
\begin{equation*}
y^{k+1} = \proj_{\mathcal{Y}}\left(y^k + \alpha \nabla_y F(x^{k+1}, y^k)\right)=\argmin_{y \in \mathcal{Y}}\left\{\|y-y^k - \alpha \nabla_y F(x^{k+1}, y^k)\|^2\right\}.
\end{equation*}
The necessary optimality condition yields
\begin{align*}
0
&\in y^{k+1}-y^k - \alpha \nabla_y F(x^{k+1}, y^k)+\partial \iota_{\mathcal{Y}}(y^{k+1})\notag\\
&=y^{k+1}-y^k - \alpha \nabla_y F(x^{k+1}, y^{k+1})+\partial \iota_{\mathcal{Y}}(y^{k+1}) +\alpha (\nabla_y F(x^{k+1}, y^{k+1})- \nabla_y F(x^{k+1}, y^{k})).
\end{align*}
Since $\partial \iota_{\mathcal{Y}} (y^{k+1})$ is the normal cone to $\mathcal{Y}$ at $y^{k+1}$, we have
\begin{align*}
v
&:=-\frac{1}{\alpha}(y^{k+1}-y^{k})+\nabla_y F(x^{k+1}, y^{k})- \nabla_y F(x^{k+1}, y^{k+1})\in -\nabla_{y} F(x^{k+1}, y^{k+1})+\partial \iota_{\mathcal{Y}}(y^{k+1}).
\end{align*}
It follows that
\begin{align*}
\|v\| \ & \leq \left(\frac{1}{\alpha}+L\right)\|y^{k+1}-y^{k}\|\\
\ &  \leq  \left(\frac{1}{\alpha}+L\right)\left(\eta\|x^{k}-x^{k+1}\|+\sigma_1\alpha L\|z^{k+1}-z^k\|+\|y_+^k(z^{k+1})-y^k\|\right) \\
\ & \leq (\eta+1+\sigma_1\alpha\beta L)\left(\frac{1}{\alpha}+L\right)\epsilon,
\end{align*}
where the first inequality is due to the $L$-Lipschitz continuity of $\nabla_y F(\cdot,\cdot)$ and the second is due to Lemma \ref{lemma-dualxy}. Putting everything together yields the desired result.
\end{proof}

\begin{proof}

As mentioned in Section \ref{sec:framework}, the global convergence rate of smoothed PLDA depends on the specific regime of the growth power $v$ in \eqref{eq:step_dual}. Let us begin by considering cases (a) and (b), i.e., either the dual function is concave or the dual problem possesses the K\L{} property with exponent $\theta\in(\frac{1}{2},1)$.


In view of the basic descent estimate in Proposition \ref{prop:decrease}, we consider the following two scenarios separately:\\
(1) There exists a $ k \in\{0,1, \ldots, K-1\}$ such that
\begin{align*}
\ &\frac{1}{2}\max \left\{\frac{3}{8\lambda}\|x^{k}-x^{k+1}\|^{2}, \frac{1}{8\alpha}\|y^{k}-y_{+}^{k}(z^{k+1})\|^2 , \frac{4r}{7\beta}\|z^{k}-z^{k+1}\|^{2}\right\}\\
\leq \ & 14r\beta\|x_r(y(z^{k+1}),z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|^{2}.
\end{align*}
(2) For any $ k \in\{0,1, \ldots, K-1\}$, we have
\begin{align*}
\ &\frac{1}{2}\max \left\{\frac{3}{8\lambda}\|x^{k}-x^{k+1}\|^{2}, \frac{1}{8\alpha}\|y^{k}-y_{+}^{k}(z^{k+1})\|^2 , \frac{4r}{7\beta}\|z^{k}-z^{k+1}\|^{2}\right\}\\
\ge\ & 14r\beta\|x_r(y(z^{k+1}),z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|^{2}.
\end{align*}

\textbf{Scenario (1)}. For the case where the K{\L} exponent $\theta \in (\tfrac{1}{2},1)$, we deduce from Proposition \ref{prop:dual_eb_KL}(b) that 
\begin{align*}
    \|y^{k}-y_{+}^{k}(z^{k+1})\|^2  & \leq 224r\alpha\beta\|x_r(y(z^{k+1}),z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|^{2}  \\ &\leq  224r\alpha\beta \omega_2^2 \|y^{k}-y_{+}^{k}(z^{k+1})\|^{\frac{1}{\theta}},  
\end{align*}
which gives $\|y^{k}-y_{+}^{k}(z^{k+1})\|\leq \rho_1\beta^{\frac{\theta}{2\theta-1}}$ with $\rho_1 := (224r\alpha\omega_2^2)^{\frac{\theta}{2\theta-1}}$. Additionally, using the update $z^{k+1} = z^k + \beta( x^{k+1} - z^k )$ and Proposition \ref{prop:dual_eb_KL}(b), we have
\begin{align*}
\|x^{k+1}-z^{k}\|^{2}  \ & =\frac{1}{\beta^2}\|z^{k+1}-z^{k}\|^{2}\\
\ &  \leq 49\|x_r(y(z^{k+1}),z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|^{2} \\
\ & \leq  49 \omega_2^2 \|y^{k}-y_{+}^{k}(z^{k+1})\|^{\frac{1}{\theta}}\leq \rho_2^2\beta^{\frac{1}{2\theta-1}},
\end{align*}
where $\rho_2 := \sqrt{49\omega_2^2\rho_1^{\frac{1}{\theta}}}$. 
Lastly, we have
\begin{align*}
    \|x^{k+1}-x^k\|^2 \ & \leq {\frac{224}{3}r\beta\lambda}\|x_r(y(z^{k+1}),z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|^{2} \\
   \  &\leq {\frac{224}{3}r\omega^2_2\beta\lambda}\|y^{k}-y_{+}^{k}(z^{k+1})\|^{\frac{1}{\theta}} \leq \rho_3^2 \beta^{\frac{2\theta}{2\theta-1}},  
\end{align*}
where $\rho_3 := \sqrt{{\frac{224}{3}r\omega_2^2\lambda}\rho_1^{\frac{1}{\theta}}}$. 
Combining the above inequalities, we have
\begin{align*}
& \max \left\{\|x^{k}-x^{k+1}\|,\|y^{k}-y_{+}^{k}(z^{k+1})\|,\|z^{k}-x^{k+1}\|\right\} \leq  \max\left\{ \rho_1\beta^{\frac{\theta}{2\theta-1}}, \rho_2\beta^{\frac{1}{4\theta-2}}, \rho_3 \beta^{\frac{\theta}{2\theta-1}}\right\}. 
\end{align*}
It then follows from Lemma \ref{lemma-episolcol}
 that $\left(x^{k+1}, y^{k+1}\right)$ is a $\rho\cdot\max\{ \rho_1\beta^{{\theta}/{(2\theta-1)}},$ $ \rho_2\beta^{1/{(4\theta-2)}}, \rho_3\beta^{{\theta}/{(2\theta-1)}}\}$-GS of problem \eqref{eq:problem}. 

 For the concave case, we can replace the primal-dual quantity $x_r( y(z^{k+1}), z^{k+1} )$ by the primal quantity $x_r^\star( z^{k+1} )$ on the right-hand side of the inequality for Scenario (1) and apply Lemma \ref{lemma-dual-bd} in Appendix \ref{sec:dual} (so that $\theta$ and $\omega_2$ are replaced by $1$ and $\kappa = \tfrac{1 + \alpha L \sigma_2 + \alpha L}{\alpha (r-L)} \cdot \textrm{diam}(\mathcal{Y})$, respectively) to conclude that $\left(x^{k+1}, y^{k+1}\right)$ is a $\max\{ \rho_1\beta, \rho_2\beta^{1/2}, \rho_3 \beta\}$-GS of problem \eqref{eq:problem}.  



Furthermore, observe that for the case where $\theta \in (\tfrac{1}{2}, 1)$, the optimization-stationarity measure of $z^{k+1}$ satisfies
\begin{equation}
\label{eq:os-gs}
\begin{aligned}
    & \|z^{k+1}-x_r^\star(z^{k+1})\| \\
    \leq\ &  \|z^{k+1}-x^{k+1}\|+\| x^{k+1} - x_r(y^k,z^k) \| + \| x_r(y^k,z^k) - x_r(y^k,z^{k+1}) \|\\
    \ & + \|x_r(y^k,z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|+ \|x_r(y_{+}^{k}(z^{k+1}), z^{k+1})-x_r^\star(z^{k+1})\|\\
     \leq\ &  (1+\sigma_1)\|z^{k}-x^{k+1}\| + \zeta\|x^{k}-x^{k+1}\| + \sigma_2 \|y^k-y_{+}^{k}(z^{k+1})\|+ \omega_2 \|y^k-y_{+}^{k}(z^{k+1})\|^{\frac{1}{2\theta}} \\
    \leq\ & \max\left\{\left(\rho_2(1+\sigma_1)+ \omega_2 \rho_1^\frac{1}{2\theta}\right)\beta^{\frac{1}{4\theta-2}},(\zeta\rho_3+\sigma_2\rho_1) \beta^{\frac{\theta}{2\theta-1}} \right\}, 
\end{aligned}
\end{equation}
where the second inequality follows from the update $z^{k+1} = z^k + \beta (x^{k+1} - z^k)$, Proposition \ref{prop:lip}, Corollary \ref{prop:dual_eb_KL2}, Lemma \ref{lemma-sollip}, and the fact that $0 < \beta \le \tfrac{1}{28}$.
It is evident that the dependence on $\beta$ is identical to that of the game-stationarity measure of $(x^{k+1}, y^{k+1})$.
For the concave case, the optimization-stationarity measure of $z^{k+1}$ can be bounded similarly.

\textbf{Scenario (2)}. Proposition \ref{prop:decrease} implies that for any $k \in\{0,1, \ldots, K-1\}$, we have 
\begin{align}
\label{eq:suff-decrease}
\Phi_r^k-\Phi_r^{k+1} 
\ge \frac{3}{16\lambda}\|x^{k}-x^{k+1}\|^{2}+\frac{1}{16\alpha}\|y^{k}-y_{+}^{k}(z^{k+1})\|^2 +\frac{2r}{7\beta}\|z^{k}-z^{k+1}\|^{2}.
\end{align}
The assumptions in case (a)  imply that 
\[ \min_{x\in\mathcal{X}}\max_{y\in\mathcal{Y}} F_r(x,y,z) = \max_{y\in\mathcal{Y}} \min_{x\in\mathcal{X}} F_r(x,y,z) \]
for all $z \in \mathbb{R}^n$ (cf.~the proof of~\citep[Lemma B.7]{zhang2020single}) and lead to the lower boundedness of $p_r$, while the assumptions in case (b) directly imply that $p_r$ is lower bounded.
In both cases, there exists a $\underline{\Phi} > -\infty$ such that for all $x \in \mathcal{X}$, $y \in \mathcal{Y}$, and $z \in \mathbb{R}^n$,
\begin{align*}
& \Phi_r(x, y, z)  = p_r(z)+(F_r(x,y,z)-d_r(y, z))+(p_r(z)-d_r(y, z))\geq p_r(z)\geq \underline{\Phi} >-\infty.
\end{align*}
It follows that
    \begin{align*}
    &\Phi_r^0-\underline{\Phi} \geq \sum_{k=0}^{K-1}\Phi_r(x^k,y^k,z^k)-\Phi_r(x^{k+1},y^{k+1},z^{k+1}) \\
    % \geq\ & \sum_{k=0}^{K-1} \frac{1}{32\lambda}\|x^{k}-x^{k+1}\|^{2}+\frac{1}{16\alpha}\|y^{k}-y_{+}^{k}(z^{k})\|^2 +\frac{2r}{7\beta}\|z^{k}-z^{k+1}\|^{2} \\
    \geq \ & \sum_{k=0}^{K-1} \min\left\{\frac{3}{16\lambda},\frac{1}{16\alpha},\frac{2\beta r}{7}\right\} \left(\|x^{k}-x^{k+1}\|^{2}+\|y^{k}-y_{+}^{k}(z^{k+1})\|^2 + \|z^{k}-x^{k+1}\|^{2} \right),
    \end{align*}
    where the last inequality is due to \eqref{eq:suff-decrease} and the update $z^{k+1}=z^{k}+\beta(x^{k+1}-z^k)$.
    In particular, there exists a $k \in\{0,1, \ldots, K-1\}$ such that
    \[
    \max \left\{\|x^{k}-x^{k+1}\|^{2},\|y^{k}-y_{+}^{k}(z^{k+1})\|^{2}, \|x^{k+1}-z^{k}\|^{2}\right\} \leq \frac{\Phi_r^0-\underline{\Phi}}{\min\left\{\frac{3}{16\lambda},\frac{1}{16\alpha},\frac{2\beta  r}{7}\right\}  K}.
    \]
% \Jiajin{continue here!}
Based on Lemma \ref{lemma-episolcol} and the fact that $0 < \beta \le \tfrac{1}{28}$,  we conclude that $\left(x^{k+1}, y^{k+1}\right)$ is an $\mathcal{O}(\sqrt{1/{K\beta}})$-GS of problem \eqref{eq:problem}. Moreover, by using the same argument as in \eqref{eq:os-gs}, we can show that $z^{k+1}$ is an $\mathcal{O}(\sqrt{1/{K\beta}})$-OS of problem \eqref{eq:problem}. Upon setting $\beta = C K^{-\frac{1}{2}}$ for the concave case and  $\beta = C K^{-\frac{2\theta-1}{2\theta}}$ for the case where the K{\L} exponent $\theta \in (\tfrac{1}{2}, 1)$, with $C$ being a suitably chosen constant, we see that the 
% where $C$ is a constant.
% Similarly, for the general concave case, we can set $\beta = C K^{-\frac{1}{2}}$. 
bounds obtained for the optimization-stationarity and game-stationarity measures are of the same order for both Scenarios (1) and (2). This establishes cases (a) and (b).

Next, let us consider case (c). First, suppose that the K{\L} exponent $\theta \in (0, \tfrac{1}{2}]$. 
Once again, we can use Proposition \ref{prop:decrease} to obtain 
\begin{align*}
\Phi_r^k-\Phi_r^{k+1} 
\ge\ &  \frac{3}{8\lambda}\|x^{k}-x^{k+1}\|^{2}+\frac{1}{8\alpha}\|y^{k}-y_{+}^{k}(z^{k+1})\|^2 +\frac{4r}{7\beta}\|z^{k}-z^{k+1}\|^{2}\\
\ & -14r\beta\|x_r(y(z^{k+1}),z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|^{2}.
\end{align*}
Using Proposition \ref{prop:dual_eb_KL}(b) and the boundedness of $\mathcal{Y}$, we have
% there exists  for each $\theta \in(0,\frac{1}{2})$ that 
\begin{equation}\label{dual-eb-bd}
\begin{aligned}
  \|x_r(y(z^{k+1}),z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|
&\leq \omega_2 \|y^{k}-y_{+}^{k}(z^{k+1})\|^{\frac{1}{2\theta}}\\
&=  \omega_2 \|y^{k}-y_{+}^{k}(z^{k+1})\|^{\frac{1}{2\theta}-1} \|y^{k}-y_{+}^{k}(z^{k+1})\|\\
&\leq   \omega_2\cdot {\rm diam}(\mathcal{Y})^{\frac{1}{2\theta}-1}\cdot \|y^{k}-y_{+}^{k}(z^{k+1})\|.
\end{aligned}
\end{equation}
It follows that
\begin{align*}
\Phi_r^k-\Phi_r^{k+1} 
\ge \ &  \frac{3}{8\lambda}\|x^{k}-x^{k+1}\|^{2}+\left(\frac{1}{8\alpha}-14r\beta\omega_2^2\cdot{\rm diam}(\mathcal{Y})^{\frac{1-2\theta}{\theta}}\right) \|y^{k}-y_{+}^{k}(z^{k+1})\|^2  +\frac{4r}{7\beta}\|z^{k}-z^{k+1}\|^{2}.
\end{align*}
Since 
$\beta  \leq \frac{ {\rm diam}(\mathcal{Y})^{\frac{2\theta-1}{\theta}}}{224 \alpha r\omega_2^2}$, we have 
\begin{align*}
&\Phi_r^k-\Phi_r^{k+1} \ge  \frac{3}{8\lambda}\|x^{k}-x^{k+1}\|^{2}+\frac{1}{16\alpha}\|y^{k}-y_{+}^{k}(z^{k+1})\|^2 +\frac{4r}{7\beta}\|z^{k}-z^{k+1}\|^{2}.
\end{align*}
The desired result can then be obtained by following a similar argument as that in the paragraph proceeding \eqref{eq:suff-decrease}.

When the K{\L} exponent $\theta=0$, we can apply Proposition \ref{prop:dual_eb_KL}(a) to derive the inequality \eqref{dual-eb-bd} 
% by letting $\theta=\frac{1}{2}$ and replacing $\omega_2$ with $\omega_1$. 
with $\theta$ and $\omega_2$ being replaced by $\tfrac{1}{2}$ and $\omega_1$, respectively.
The desired result then follows by adapting the argument in the preceding paragraph.
\end{proof}

\begin{fact}\label{fact-1}
The functions $F(\cdot, y)$ for any $y\in\mathcal{Y}$ and $f$ are $L$-weakly convex on $\mathcal{X}$.
\end{fact}

\begin{fact}\label{fact-2}
Let $y\in\R^d$ and $r>0$ be given. For all $x, \bar{x} \in\mathcal{X}$, we have
\[
-\frac{r^{-1}+L}{2}\|x-\bar{x}\|^{2} \leq F(x,y)-F_{\bar{x},r}(x, y) \leq \frac{-r^{-1} + L}{2}\|x-\bar{x}\|^{2} .
\]
\end{fact}

\begin{lemma}\label{lemma-sollip}
For any $y, y^{\prime} \in \mathcal{Y}$ and $z, z^{\prime} \in \R^n$, we have 
    \begin{align}
        &\|x_r(y, z)-x_r(y, z^{\prime})\| \leq \sigma_{1}\|z-z^{\prime}\|, \label{lip-z}\\
        &\|x_r^\star(z)-x_r^\star(z^{\prime})\| \leq \sigma_{1}\|z-z^{\prime}\|, \label{lip-starz}\\
        &\|x_r(y, z)-x_r(y^{\prime}, z)\| \leq \sigma_{2}\|y-y^{\prime}\|, \label{lip-y}
        \end{align}
     where $\sigma_{1}:=\frac{r}{r-L}$ and $\sigma_{2}:=\frac{2r-L}{r-L}$.
    \end{lemma}

\begin{proof}
From the definition of $F_r$, we know that for any $x\in\mathcal{X}$, $y\in\mathcal{Y}$, and $z,z'\in\R^n$, 
\begin{equation}\label{func-cal}
F_r(x,y,z^{\prime})-F_r(x,y,z)=\frac{r}{2}(\|x-z'\|^2-\|x-z\|^2)=\frac{r}{2}(\|z^{\prime}\|^{2}-2(z^{\prime}-z)^\top x-\|z\|^{2}).
\end{equation}
Fact \ref{fact-1} implies that $F(\cdot, y)$ is $L$-weakly convex for any $y \in \mathcal{Y}$. Therefore, for any $x\in\mathcal{X}$, $y\in\mathcal{Y}$, and $z\in\R^n$, we have
\begin{equation}\label{psi-strongcvx}
F_r(x,y, z)- F_r(x_r(y,z),y,z)
\geq \frac{r-L}{2}\|x-x_r(y,z)\|^{2}.
\end{equation}
Combining \eqref{func-cal} and \eqref{psi-strongcvx} yields
\begin{align}\label{lip-key1}
    &F_r(x_r(y,z),y,z^{\prime})-F_r(x_r(y,z^{\prime}),y,z^{\prime}) \notag\\
    =\ &F_r(x_r(y,z),y,z^{\prime})-F_r(x_r(y,z),y,z)+F_r(x_r(y,z),y,z)-F_r(x_r(y,z^{\prime}),y,z)\, \notag\\
    &-(F_r(x_r(y,z^{\prime}),y, z^{\prime})-F_r(x_r(y,z^{\prime}),y, z)) \notag\\
    \leq\ &\frac{r}{2}(\|z^{\prime}\|^{2}-2(z^{\prime}-z)^\top x_r(y,z)-\|z\|^{2})-\frac{r-L}{2}\|x_r(y,z)-x_r(y,z^{\prime})\|^{2}\,  \notag\\
    &-\frac{r}{2}(\|z^{\prime}\|^{2}-2(z^{\prime}-z)^\top x_r(y,z^{\prime})-\|z\|^{2}) \notag\\
    \leq\ &r(z^{\prime}-z)^\top(x_r(y,z^{\prime})-x_r(y,z))-\frac{r-L}{2}\|x_r(y,z)-x_r(y,z^{\prime})\|^{2}.
    \end{align}
 On the other hand, \eqref{psi-strongcvx} implies that
    \[
    F_r(x_r(y,z),y, z^{\prime})-F_r(x_r(y,z^{\prime}),y,z^{\prime}) \geq \frac{r-L}{2}\|x_r(y,z)-x_r(y,z^{\prime})\|^{2}.
    \]
Combining this inequality with \eqref{lip-key1}, we get
    \[
    (r-L)\|x_r(y,z)-x_r(y,z^{\prime})\|^{2}\leq r(z^{\prime}-z)^\top (x_r(y,z^{\prime})-x_r(y,z)).
    \]
Using the Cauchy-Schwarz inequality, we obtain
    \[
    \|x_r(y,z)-x_r(y,z^{\prime})\| \leq \frac{r}{r-L}\|z-z^{\prime}\|.
    \]
Therefore, we conclude that \eqref{lip-z} holds with $\sigma_1=\frac{r}{r-L}$. Since $f=\max_{y \in \mathcal{Y}} F(\cdot,y)$ is also $L$-weakly convex by  Fact \ref{fact-1}, we can prove that \eqref{lip-starz} holds by using a similar argument as above.


We  now proceed to prove \eqref{lip-y}. Using \eqref{psi-strongcvx}, we have
\begin{align}
&F_r(x_r(y^{\prime}, z),y, z)-F_r(x_r(y, z), y,z) \geq \frac{r-L}{2}\|x_r(y, z)-x_r(y^{\prime}, z)\|^{2},\label{psi-strongcvxineq1} \\
&F_r(x_r(y, z), y^{\prime},z)-F_r(x_r(y^{\prime}, z), y^{\prime},z) \geq \frac{r-L}{2}\|x_r(y, z)-x_r(y^{\prime}, z)\|^{2}\label{psi-strongcvxineq2}.
\end{align}
Moreover, by the $L$-Lipschitz continuity of $\nabla_{y} F_r(x, \cdot, z)$ for any $x \in \mathcal{X}$ and $z \in \mathbb{R}^n$, we have
\begin{equation}
\begin{aligned}\label{psi-yconcave}
 F_r(x_r(y, z), y^{\prime},z)-F_r(x_r(y, z), y,z)\leq &\langle\nabla_{y} F_r(x_r(y, z),y,z), y^{\prime}-y\rangle +\frac{L}{2}\|y-y^{\prime}\|^{2}
\end{aligned}
\end{equation}
and 
\begin{equation}
\begin{aligned}\label{psi-ylip}
 F_r(x_r(y^{\prime}, z), y, z)-F_r(x_r(y^{\prime}, z), y^{\prime},z) \leq & \langle\nabla_{y} F_r(x_r(y^{\prime}, z), y^{\prime}, z), y-y^{\prime}\rangle + \frac{L}{2}\|y-y^{\prime}\|^{2}.
\end{aligned}
\end{equation}
Incorporating \eqref{psi-strongcvxineq1}--\eqref{psi-ylip}, we obtain
\begin{equation*}
% \label{lip-key2}
\begin{aligned}
& (r-L)\|x_r(y, z)-x_r(y^{\prime}, z)\|^{2}  \\ \leq \ &\langle\nabla_{y} F_r(x_r(y, z), y, z)-\nabla_{y} F_r(x_r(y^{\prime}, z), y^{\prime}, z), y^{\prime}-y\rangle +L\|y-y^{\prime}\|^{2}. 
\end{aligned}
\end{equation*}
Since $\nabla_y F_r(\cdot,\cdot,z) = \nabla_y F(\cdot,\cdot)$ is $L$-Lipschitz for any $z \in \mathbb{R}^n$, we have
\begin{align*}
&\|\nabla_{y} F_r(x_r(y, z), y, z)-\nabla_{y} F_r(x_r(y^{\prime}, z), y^{\prime}, z)\| \notag\\
\leq\ &\|\nabla_{y} F_r(x_r(y, z), y, z)-\nabla_{y}F_r(x_r(y, z), y^{\prime}, z)\|  +\|\nabla_{y}F_r(x_r(y, z), y^{\prime}, z)-\nabla_{y} F_r(x_r(y^{\prime}, z), y^{\prime}, z)\|\notag\\
\leq\ &L(\|y-y^{\prime}\|+\|x_r(y^{\prime}, z)-x_r(y, z)\|).\notag
\end{align*}
It follows that
\begin{align*}
(r-L)\|x_r(y, z)-x_r(y^{\prime}, z)\|^{2} 
\leq L\|x_r(y^{\prime}, z)-x_r(y, z)\|\cdot\|y-y^{\prime}\|+2L\|y-y^{\prime}\|^{2}.
\end{align*}
Let $\zeta:=\frac{\|x_r(y, z)-x_r(y^{\prime}, z)\|}{\|y-y^{\prime}\|}$. 
Then, the above inequality gives
\begin{align*}
\zeta^{2}
& \ \leq \frac{L}{r-L} \zeta+\frac{2L}{(r-L)}\leq \frac{1}{2}\zeta^2+\frac{L^2}{2(r-L)^2} +\frac{2L}{(r-L)}\\
& \ \leq \frac{1}{2} \zeta^{2}+\frac{L^2+4L(r-L)}{2(r-L)^2}  \leq \frac{1}{2} \zeta^{2}+\frac{(L+2(r-L))^2}{2(r-L)^2},
\end{align*}
where the second inequality holds because $ab\leq \frac{1}{2}(a^2+b^2)$ for any $a,b\in\R$. Thus, we get
\[
\|x_r(y, z)-x_r(y^{\prime}, z)\| \leq  \frac{2r-L}{r-L}\|y-y^{\prime}\|,
\]
which shows that \eqref{lip-y} holds with $\sigma_{2}=\frac{2r-L}{r-L}$. The proof is complete.
\end{proof}

\begin{lemma}\label{lemma-dualdiff} 
    The dual potential value function $d_r$ is differentiable on $\mathcal{Y}\times \R^n$ with
    \begin{align*}
    &\nabla_{y} d_r(y,z)=\nabla_{y} F(x_r(y,z),y),\\
    &\nabla_{z} d_r(y,z)=\nabla_{z} F_r(x_r(y, z),y, z)=r(z-x_r(y,z))
    \end{align*}
    for any $y \in \mathcal{Y}$ and $z \in \mathbb{R}^n$. Moreover, for any $y \in \mathcal{Y}$ and $z \in \mathbb{R}^n$,  the gradients $\nabla_y d_r(\cdot,z)$ and $\nabla_z d_r(y,\cdot)$ are Lipschitz continuous, i.e.,
    \begin{align}
    &\|\nabla_{y} d_r(y^{\prime},z)-\nabla_{y} d_r(y^{\prime \prime},z)\| \leq L_{d_r}\|y^{\prime}-y^{\prime \prime}\| \quad \text{for all}\ y^{\prime}, y^{\prime \prime} \in \mathcal{Y},\notag\\
    &\|\nabla_{z} d_r(y,z')-\nabla_{z} d_r(y,z'')\| \leq L_{d_r}'\|z^{\prime}-z^{\prime \prime}\| \quad \text{for all}\ z^{\prime}, z^{\prime \prime} \in \R^n,\notag
    \end{align}
    where $L_{d_r}:=(\sigma_{2}+1)L$ and $L_{d_r}':=(\sigma_1 + 1)r$.
    \end{lemma}

\begin{proof}
Since $F_r(\cdot,y,z)$ is strongly convex, $F_r(x,\cdot,z)$ is weakly concave, and $F_r(x,y,\cdot)$ is strongly convex for any $x \in \mathcal{X}$, $y \in \mathcal{Y}$, and $z \in \mathbb{R}^n$, the function
    \[
    d_r(\cdot,\cdot)=\min_{x\in\mathcal{X}} F_r(x,\cdot,\cdot)
    \] 
    is differentiable on $\mathcal{Y}\times \R^n$ due to \citep[Theorem 10.31]{rockafellar2009variational}. In particular, for any $y\in\mathcal{Y}$ and $z\in\R^n$, one has
    \[
    \nabla_{y} d_r(y, z)=\nabla_{y} F_r(x_r(y, z),y, z)=\nabla_{y} F(x_r(y, z), y).
    \]
Using  \citep[Lemma 4.3]{drusvyatskiy2019efficiency}, we have 
    \[
    \nabla_{z} d_r(y,z)=\nabla_{z} F_r(x_r(y, z),y, z)=r(z-\prox_{\frac{1}{r}F(\cdot,y)+\iota_{\mathcal{X}}}(z))=r(z-x_r(y,z)).
    \]
    It follows that for  any $y^{\prime}, y^{\prime \prime} \in \mathcal{Y}$, 
    \begin{align*}
    &\|\nabla_{y} d_r(y^{\prime}, z)-\nabla_{y} d_r(y^{\prime \prime}, z)\|\notag\\
    =\ &\|\nabla_{y} F_r(x_r(y^{\prime}, z), y^{\prime},z)-\nabla_{y} F_r(x_r(y^{\prime \prime}, z), y^{\prime \prime},z)\| \\
    \leq\ &\|\nabla_{y} F_r(x_r(y^{\prime}, z), y^{\prime},z)-\nabla_{y} F_r(x_r(y^{\prime}, z), y^{\prime \prime}, z)\|+\|\nabla_{y} F_r(x_r(y^{\prime}, z), y^{\prime \prime},z)-\nabla_{y} F_r(x_r(y^{\prime \prime}, z), y^{\prime \prime}, z)\| \\
    \leq\ & L\|y^{\prime}-y^{\prime \prime}\|+L\|x_r(y^{\prime}, z)-x_r(y^{\prime \prime}, z)\|\notag\\
    \leq\ & L\|y^{\prime}-y^{\prime \prime}\|+L \sigma_{2}\|y^{\prime}-y^{\prime \prime}\|\leq L_{d_r}\|y^{\prime}-y^{\prime \prime}\|,
    \end{align*}
    where the third inequality is due to \eqref{lip-y}. Moreover, we have
    \begin{align*}
    \|\nabla_{z} d_r(y,z')-\nabla_{z} d_r(y,z'')\|=\ &r\|z'-x_r(y,z')-(z''-x_r(y,z''))\| \\
    \leq\ & r\|z^{\prime}-z^{\prime \prime}\|+r\|x_r(y, z')-x_r(y, z'')\| \\
    \leq\ & r\|z^{\prime}-z^{\prime \prime}\|+ r\sigma_{1}\|z^{\prime}-z^{\prime \prime}\|\leq L_{d_r}'\|z^{\prime}-z^{\prime \prime}\|,
    \end{align*}
where the second inequality is due to \eqref{lip-z}. The proof is complete.
\end{proof}

\begin{lemma}\label{lemma-dualxy}
For any $k\ge0$, we have
    \begin{equation*}
        \|y^{k+1}-y_{+}^{k}(z^{k+1})\| \leq \eta \|x^{k}-x^{k+1}\|+\sigma_1\alpha L\|z^{k+1}-z^k\|,
        \end{equation*}
where $\eta:=\alpha L \zeta$.
\end{lemma}

\begin{proof}
We compute
\begin{equation*}
% \label{iter-result2}
\begin{aligned}
\ &\|y^{k+1}-y_{+}^{k}(z^{k+1})\|\\ =\ &\|\proj_{\mathcal{Y}}(y^{k}+\alpha \nabla_{y} F(x^{k+1},y^{k}))-\proj_{\mathcal{Y}}(y^{k}+\alpha \nabla_{y} F(x_r(y^{k}, z^{k+1}),y^{k}))\|\notag \\
\leq\ &\|y^{k}+\alpha \nabla_{y} F(x^{k+1}, y^{k})-(y^{k}+\alpha \nabla_{y} F(x_r(y^{k}, z^{k+1}),  y^{k}))\|\notag \\
\leq\ & \alpha L(\|x^{k+1}-x_r(y^{k}, z^{k})\|+\|x_r(y^{k}, z^{k})-x_r(y^{k}, z^{k+1})\|) \notag \\
\leq\ & \eta\|x^{k}-x^{k+1}\|+\sigma_1\alpha L\|z^{k+1}-z^k\|,
\end{aligned}
\end{equation*}
where the first inequality is due to the nonexpansiveness of the projection operator, the second is due to the $L$-Lipschitz continuity of $\nabla_y F(\cdot,\cdot)$, and the third follows from Proposition \ref{prop:lip} and \eqref{lip-z}. The proof is complete.
\end{proof}

\begin{lemma}[Primal descent]
\label{lemma-F-des} 
For any $k\ge0$, we have
\begin{align*}
& F_r(x^{k}, y^{k},z^k)-F_r(x^{k+1}, y^{k+1},z^{k+1})\\
\ge\ &
\frac{2\lambda^{-1}+r-L}{2}\|x^k-x^{k+1}\|^2 + \langle\nabla_{y} F_r(x^{k+1}, y^{k},z^k), y^{k}-y^{k+1}\rangle-\frac{L}{2}\|y^k-y^{k+1}\|^2 \\  &  +\frac{(2-\beta)r}{2 \beta}\|z^{k}-z^{k+1}\|^{2}. 
\end{align*}
\end{lemma}

\begin{proof}
One can infer from the definition that $F_{x^k,\lambda}(\cdot,y^k)$ is $\lambda^{-1}$-strongly convex. Therefore, we have
\begin{equation*}
\begin{aligned}
F_r(x^{k}, y^{k},z^{k}) & =F(x^{k}, y^{k})+ \frac{r}{2}\|x^k-z^{k}\|^2  = F_{x^k,\lambda}(x^k,y^k) + \frac{r}{2}\|x^k-z^{k}\|^2 \\
& \ge F_{x^k,\lambda}(x^{k+1},y^k)+\frac{r}{2}\|x^{k+1}-z^{k}\|^2+\frac{\lambda^{-1}+r}{2}\|x^k-x^{k+1}\|^2.
\end{aligned}
\end{equation*}
Moreover, Fact \ref{fact-2} implies that
\begin{equation*} 
F_{x^k,\lambda}(x^{k+1},y^k)\ge F(x^{k+1},y^k) + \frac{\lambda^{-1}-L}{2}\|x^{k+1}-x^k\|^2.
\end{equation*}
It follows that
\begin{align}\label{primaldec-key1}
F_r(x^{k},y^{k}, z^k) &\ge F(x^{k+1},y^k)+\frac{r}{2}\|x^{k+1}-z^k\|^2+\frac{2\lambda^{-1}+r-L}{2}\|x^k-x^{k+1}\|^2\notag\\
&= F_r(x^{k+1},y^{k}, z^{k})+\frac{2\lambda^{-1}+r-L}{2}\|x^k-x^{k+1}\|^2.
\end{align}
Next,  as $\nabla_y F_r(x,\cdot,z)$ is $L$-Lipschitz continuous for any $x\in\mathcal{X}$ and $z\in\R^n$, we have 
    \begin{align}\label{primaldec-key2}
        F_r(x^{k+1}, y^{k},z^k)-F_r(x^{k+1}, y^{k+1},z^k) \ge \langle\nabla_{y} F_r(x^{k+1},y^{k}, z^k), y^{k}-y^{k+1}\rangle-\frac{L}{2}\|y^k-y^{k+1}\|^2.
    \end{align}
At last, based on the update $z^{k+1}=z^{k}+\beta(x^{k+1}-z^{k})$, we get
\begin{equation}\label{primaldec-key3}
F_r(x^{k+1}, y^{k+1},z^{k})-F_r(x^{k+1},y^{k+1}, z^{k+1})  = \frac{(2-\beta)r}{2 \beta}\|z^{k}-z^{k+1}\|^{2}.
\end{equation}
By summing up \eqref{primaldec-key1}, \eqref{primaldec-key2}, and \eqref{primaldec-key3}, we obtain the desired result.
\end{proof}

\begin{lemma}[Dual ascent]\label{lemma-d-aes} 
For any $k\ge0$, we have
\begin{equation*}
% \label{dual-ascent}
 \begin{aligned}
    \ & d_r(y^{k+1},z^{k+1})-d_r(y^{k},z^k)\\
    \ge\ &\langle\nabla_{y} F_r(x_r(y^{k}, z^{k}),  y^{k}, z^{k}), y^{k+1}-y^{k}\rangle-\frac{L_{d_r}}{2}\|y^{k}-y^{k+1}\|^{2}\,\\
    &+\frac{r}{2}\left\langle z^{k+1}-z^{k},z^{k+1}+z^{k}-2 x_r(y^{k+1}, z^{k+1})\right\rangle. 
    \end{aligned}
\end{equation*}
\end{lemma}

\begin{proof}
Based on Lemma \ref{lemma-dualdiff}, $\nabla_{y} d_r(\cdot,z)$ is $L_{d_r}$-Lipschitz continuous for any $z \in \mathbb{R}^n$. Thus, we have 
        \begin{align*}
        \ & d_r(y^{k+1},z^k)-d_r(y^{k},z^k)  
        \geq \langle\nabla_{y} d_r(y^{k},z^k), y^{k+1}-y^{k}\rangle-\frac{L_{d_r}}{2}\|y^{k}-y^{k+1}\|^{2} \\
        =\ & \langle \nabla_{y} F_r(x_r(y^{k}, z^{k}), y^{k}, z^{k}), y^{k+1}-y^{k}\rangle-\frac{L_{d_r}}{2}\|y^{k}-y^{k+1}\|^{2}.
        \end{align*}
In addition, one has 
        \begin{align*}
        &d_r(y^{k+1}, z^{k+1})-d_r(y^{k+1}, z^{k})\notag\\ 
        =\ & F_r(x_r(y^{k+1}, z^{k+1}), y^{k+1}, z^{k+1})-F_r(x_r(y^{k+1}, z^{k}), y^{k+1},z^{k}) \\
        \geq\ &  F_r(x_r(y^{k+1}, z^{k+1}), y^{k+1},z^{k+1})-F_r(x_r(y^{k+1}, z^{k+1}), y^{k+1},z^{k}) \\
        =\ & \frac{r}{2}\|x_r(y^{k+1}, z^{k+1})-z^{k+1}\|^{2}-\frac{r}{2}\|x_r(y^{k+1}, z^{k+1})-z^{k}\|^{2} \\
        =\ & \frac{r}{2} \left\langle z^{k+1}-z^{k},z^{k+1}+z^{k}-2 x_r(y^{k+1}, z^{k+1})\right\rangle.
        \end{align*}
Finally, by combining the above inequalities, the proof is complete.
\end{proof}

\begin{lemma}[Proximal descent (smoothness)]
\label{lemma-p-des} 
    For any $k\ge0$, we have
   \begin{equation*}
   % \label{proximal-descent}
    p_r(z^k)-p_r(z^{k+1}) \ge \frac{r}{2}\left\langle z^{k+1}-z^{k},2 x_r(y(z^{k+1}), z^{k})-z^{k}-z^{k+1}\right\rangle, 
    \end{equation*}
    where $y(z^{k+1})\in Y(z^{k+1})$.
    \end{lemma}

\begin{proof}
% From Sion's minimax theorem \citep{sion1958general}, we know that
