    \geq \ & \sum_{k=0}^{K-1} \min\left\{\frac{3}{16\lambda},\frac{1}{16\alpha},\frac{2\beta r}{7}\right\} \left(\|x^{k}-x^{k+1}\|^{2}+\|y^{k}-y_{+}^{k}(z^{k+1})\|^2 + \|z^{k}-x^{k+1}\|^{2} \right),
    \end{align*}
    where the last inequality is due to \eqref{eq:suff-decrease} and the update $z^{k+1}=z^{k}+\beta(x^{k+1}-z^k)$.
    In particular, there exists a $k \in\{0,1, \ldots, K-1\}$ such that
    \[
    \max \left\{\|x^{k}-x^{k+1}\|^{2},\|y^{k}-y_{+}^{k}(z^{k+1})\|^{2}, \|x^{k+1}-z^{k}\|^{2}\right\} \leq \frac{\Phi_r^0-\underline{\Phi}}{\min\left\{\frac{3}{16\lambda},\frac{1}{16\alpha},\frac{2\beta  r}{7}\right\}  K}.
    \]
