bounds obtained for the optimization-stationarity and game-stationarity measures are of the same order for both Scenarios (1) and (2). This establishes cases (a) and (b).

Next, let us consider case (c). First, suppose that the K{\L} exponent $\theta \in (0, \tfrac{1}{2}]$. 
Once again, we can use Proposition \ref{prop:decrease} to obtain 
\begin{align*}
\Phi_r^k-\Phi_r^{k+1} 
\ge\ &  \frac{3}{8\lambda}\|x^{k}-x^{k+1}\|^{2}+\frac{1}{8\alpha}\|y^{k}-y_{+}^{k}(z^{k+1})\|^2 +\frac{4r}{7\beta}\|z^{k}-z^{k+1}\|^{2}\\
\ & -14r\beta\|x_r(y(z^{k+1}),z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|^{2}.
\end{align*}
Using Proposition \ref{prop:dual_eb_KL}(b) and the boundedness of $\mathcal{Y}$, we have
% there exists  for each $\theta \in(0,\frac{1}{2})$ that 
\begin{equation}\label{dual-eb-bd}
\begin{aligned}
  \|x_r(y(z^{k+1}),z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|
&\leq \omega_2 \|y^{k}-y_{+}^{k}(z^{k+1})\|^{\frac{1}{2\theta}}\\
&=  \omega_2 \|y^{k}-y_{+}^{k}(z^{k+1})\|^{\frac{1}{2\theta}-1} \|y^{k}-y_{+}^{k}(z^{k+1})\|\\
&\leq   \omega_2\cdot {\rm diam}(\mathcal{Y})^{\frac{1}{2\theta}-1}\cdot \|y^{k}-y_{+}^{k}(z^{k+1})\|.
\end{aligned}
\end{equation}
It follows that
\begin{align*}
\Phi_r^k-\Phi_r^{k+1} 
\ge \ &  \frac{3}{8\lambda}\|x^{k}-x^{k+1}\|^{2}+\left(\frac{1}{8\alpha}-14r\beta\omega_2^2\cdot{\rm diam}(\mathcal{Y})^{\frac{1-2\theta}{\theta}}\right) \|y^{k}-y_{+}^{k}(z^{k+1})\|^2  +\frac{4r}{7\beta}\|z^{k}-z^{k+1}\|^{2}.
\end{align*}
Since 
$\beta  \leq \frac{ {\rm diam}(\mathcal{Y})^{\frac{2\theta-1}{\theta}}}{224 \alpha r\omega_2^2}$, we have 
\begin{align*}
&\Phi_r^k-\Phi_r^{k+1} \ge  \frac{3}{8\lambda}\|x^{k}-x^{k+1}\|^{2}+\frac{1}{16\alpha}\|y^{k}-y_{+}^{k}(z^{k+1})\|^2 +\frac{4r}{7\beta}\|z^{k}-z^{k+1}\|^{2}.
\end{align*}
The desired result can then be obtained by following a similar argument as that in the paragraph proceeding \eqref{eq:suff-decrease}.

When the K{\L} exponent $\theta=0$, we can apply Proposition \ref{prop:dual_eb_KL}(a) to derive the inequality \eqref{dual-eb-bd} 
% by letting $\theta=\frac{1}{2}$ and replacing $\omega_2$ with $\omega_1$. 
with $\theta$ and $\omega_2$ being replaced by $\tfrac{1}{2}$ and $\omega_1$, respectively.
The desired result then follows by adapting the argument in the preceding paragraph.
\end{proof}

\begin{fact}\label{fact-1}
The functions $F(\cdot, y)$ for any $y\in\mathcal{Y}$ and $f$ are $L$-weakly convex on $\mathcal{X}$.
\end{fact}

\begin{fact}\label{fact-2}
Let $y\in\R^d$ and $r>0$ be given. For all $x, \bar{x} \in\mathcal{X}$, we have
\[
-\frac{r^{-1}+L}{2}\|x-\bar{x}\|^{2} \leq F(x,y)-F_{\bar{x},r}(x, y) \leq \frac{-r^{-1} + L}{2}\|x-\bar{x}\|^{2} .
\]
\end{fact}

\begin{lemma}\label{lemma-sollip}
For any $y, y^{\prime} \in \mathcal{Y}$ and $z, z^{\prime} \in \R^n$, we have 
    \begin{align}
        &\|x_r(y, z)-x_r(y, z^{\prime})\| \leq \sigma_{1}\|z-z^{\prime}\|, \label{lip-z}\\
        &\|x_r^\star(z)-x_r^\star(z^{\prime})\| \leq \sigma_{1}\|z-z^{\prime}\|, \label{lip-starz}\\
        &\|x_r(y, z)-x_r(y^{\prime}, z)\| \leq \sigma_{2}\|y-y^{\prime}\|, \label{lip-y}
        \end{align}
     where $\sigma_{1}:=\frac{r}{r-L}$ and $\sigma_{2}:=\frac{2r-L}{r-L}$.
    \end{lemma}

\begin{proof}
From the definition of $F_r$, we know that for any $x\in\mathcal{X}$, $y\in\mathcal{Y}$, and $z,z'\in\R^n$, 
\begin{equation}\label{func-cal}
F_r(x,y,z^{\prime})-F_r(x,y,z)=\frac{r}{2}(\|x-z'\|^2-\|x-z\|^2)=\frac{r}{2}(\|z^{\prime}\|^{2}-2(z^{\prime}-z)^\top x-\|z\|^{2}).
\end{equation}
Fact \ref{fact-1} implies that $F(\cdot, y)$ is $L$-weakly convex for any $y \in \mathcal{Y}$. Therefore, for any $x\in\mathcal{X}$, $y\in\mathcal{Y}$, and $z\in\R^n$, we have
\begin{equation}\label{psi-strongcvx}
F_r(x,y, z)- F_r(x_r(y,z),y,z)
\geq \frac{r-L}{2}\|x-x_r(y,z)\|^{2}.
\end{equation}
Combining \eqref{func-cal} and \eqref{psi-strongcvx} yields
\begin{align}\label{lip-key1}
    &F_r(x_r(y,z),y,z^{\prime})-F_r(x_r(y,z^{\prime}),y,z^{\prime}) \notag\\
    =\ &F_r(x_r(y,z),y,z^{\prime})-F_r(x_r(y,z),y,z)+F_r(x_r(y,z),y,z)-F_r(x_r(y,z^{\prime}),y,z)\, \notag\\
    &-(F_r(x_r(y,z^{\prime}),y, z^{\prime})-F_r(x_r(y,z^{\prime}),y, z)) \notag\\
    \leq\ &\frac{r}{2}(\|z^{\prime}\|^{2}-2(z^{\prime}-z)^\top x_r(y,z)-\|z\|^{2})-\frac{r-L}{2}\|x_r(y,z)-x_r(y,z^{\prime})\|^{2}\,  \notag\\
    &-\frac{r}{2}(\|z^{\prime}\|^{2}-2(z^{\prime}-z)^\top x_r(y,z^{\prime})-\|z\|^{2}) \notag\\
    \leq\ &r(z^{\prime}-z)^\top(x_r(y,z^{\prime})-x_r(y,z))-\frac{r-L}{2}\|x_r(y,z)-x_r(y,z^{\prime})\|^{2}.
    \end{align}
 On the other hand, \eqref{psi-strongcvx} implies that
    \[
    F_r(x_r(y,z),y, z^{\prime})-F_r(x_r(y,z^{\prime}),y,z^{\prime}) \geq \frac{r-L}{2}\|x_r(y,z)-x_r(y,z^{\prime})\|^{2}.
    \]
Combining this inequality with \eqref{lip-key1}, we get
    \[
    (r-L)\|x_r(y,z)-x_r(y,z^{\prime})\|^{2}\leq r(z^{\prime}-z)^\top (x_r(y,z^{\prime})-x_r(y,z)).
    \]
Using the Cauchy-Schwarz inequality, we obtain
    \[
    \|x_r(y,z)-x_r(y,z^{\prime})\| \leq \frac{r}{r-L}\|z-z^{\prime}\|.
    \]
Therefore, we conclude that \eqref{lip-z} holds with $\sigma_1=\frac{r}{r-L}$. Since $f=\max_{y \in \mathcal{Y}} F(\cdot,y)$ is also $L$-weakly convex by  Fact \ref{fact-1}, we can prove that \eqref{lip-starz} holds by using a similar argument as above.


We  now proceed to prove \eqref{lip-y}. Using \eqref{psi-strongcvx}, we have
\begin{align}
&F_r(x_r(y^{\prime}, z),y, z)-F_r(x_r(y, z), y,z) \geq \frac{r-L}{2}\|x_r(y, z)-x_r(y^{\prime}, z)\|^{2},\label{psi-strongcvxineq1} \\
&F_r(x_r(y, z), y^{\prime},z)-F_r(x_r(y^{\prime}, z), y^{\prime},z) \geq \frac{r-L}{2}\|x_r(y, z)-x_r(y^{\prime}, z)\|^{2}\label{psi-strongcvxineq2}.
\end{align}
Moreover, by the $L$-Lipschitz continuity of $\nabla_{y} F_r(x, \cdot, z)$ for any $x \in \mathcal{X}$ and $z \in \mathbb{R}^n$, we have
\begin{equation}
\begin{aligned}\label{psi-yconcave}
 F_r(x_r(y, z), y^{\prime},z)-F_r(x_r(y, z), y,z)\leq &\langle\nabla_{y} F_r(x_r(y, z),y,z), y^{\prime}-y\rangle +\frac{L}{2}\|y-y^{\prime}\|^{2}
\end{aligned}
\end{equation}
and 
\begin{equation}
\begin{aligned}\label{psi-ylip}
 F_r(x_r(y^{\prime}, z), y, z)-F_r(x_r(y^{\prime}, z), y^{\prime},z) \leq & \langle\nabla_{y} F_r(x_r(y^{\prime}, z), y^{\prime}, z), y-y^{\prime}\rangle + \frac{L}{2}\|y-y^{\prime}\|^{2}.
\end{aligned}
\end{equation}
Incorporating \eqref{psi-strongcvxineq1}--\eqref{psi-ylip}, we obtain
\begin{equation*}
% \label{lip-key2}
\begin{aligned}
& (r-L)\|x_r(y, z)-x_r(y^{\prime}, z)\|^{2}  \\ \leq \ &\langle\nabla_{y} F_r(x_r(y, z), y, z)-\nabla_{y} F_r(x_r(y^{\prime}, z), y^{\prime}, z), y^{\prime}-y\rangle +L\|y-y^{\prime}\|^{2}. 
\end{aligned}
\end{equation*}
Since $\nabla_y F_r(\cdot,\cdot,z) = \nabla_y F(\cdot,\cdot)$ is $L$-Lipschitz for any $z \in \mathbb{R}^n$, we have
\begin{align*}
&\|\nabla_{y} F_r(x_r(y, z), y, z)-\nabla_{y} F_r(x_r(y^{\prime}, z), y^{\prime}, z)\| \notag\\
\leq\ &\|\nabla_{y} F_r(x_r(y, z), y, z)-\nabla_{y}F_r(x_r(y, z), y^{\prime}, z)\|  +\|\nabla_{y}F_r(x_r(y, z), y^{\prime}, z)-\nabla_{y} F_r(x_r(y^{\prime}, z), y^{\prime}, z)\|\notag\\
\leq\ &L(\|y-y^{\prime}\|+\|x_r(y^{\prime}, z)-x_r(y, z)\|).\notag
\end{align*}
It follows that
\begin{align*}
(r-L)\|x_r(y, z)-x_r(y^{\prime}, z)\|^{2} 
\leq L\|x_r(y^{\prime}, z)-x_r(y, z)\|\cdot\|y-y^{\prime}\|+2L\|y-y^{\prime}\|^{2}.
\end{align*}
Let $\zeta:=\frac{\|x_r(y, z)-x_r(y^{\prime}, z)\|}{\|y-y^{\prime}\|}$. 
Then, the above inequality gives
\begin{align*}
\zeta^{2}
& \ \leq \frac{L}{r-L} \zeta+\frac{2L}{(r-L)}\leq \frac{1}{2}\zeta^2+\frac{L^2}{2(r-L)^2} +\frac{2L}{(r-L)}\\
& \ \leq \frac{1}{2} \zeta^{2}+\frac{L^2+4L(r-L)}{2(r-L)^2}  \leq \frac{1}{2} \zeta^{2}+\frac{(L+2(r-L))^2}{2(r-L)^2},
\end{align*}
where the second inequality holds because $ab\leq \frac{1}{2}(a^2+b^2)$ for any $a,b\in\R$. Thus, we get
\[
\|x_r(y, z)-x_r(y^{\prime}, z)\| \leq  \frac{2r-L}{r-L}\|y-y^{\prime}\|,
\]
which shows that \eqref{lip-y} holds with $\sigma_{2}=\frac{2r-L}{r-L}$. The proof is complete.
\end{proof}

\begin{lemma}\label{lemma-dualdiff} 
    The dual potential value function $d_r$ is differentiable on $\mathcal{Y}\times \R^n$ with
    \begin{align*}
    &\nabla_{y} d_r(y,z)=\nabla_{y} F(x_r(y,z),y),\\
    &\nabla_{z} d_r(y,z)=\nabla_{z} F_r(x_r(y, z),y, z)=r(z-x_r(y,z))
    \end{align*}
    for any $y \in \mathcal{Y}$ and $z \in \mathbb{R}^n$. Moreover, for any $y \in \mathcal{Y}$ and $z \in \mathbb{R}^n$,  the gradients $\nabla_y d_r(\cdot,z)$ and $\nabla_z d_r(y,\cdot)$ are Lipschitz continuous, i.e.,
    \begin{align}
    &\|\nabla_{y} d_r(y^{\prime},z)-\nabla_{y} d_r(y^{\prime \prime},z)\| \leq L_{d_r}\|y^{\prime}-y^{\prime \prime}\| \quad \text{for all}\ y^{\prime}, y^{\prime \prime} \in \mathcal{Y},\notag\\
    &\|\nabla_{z} d_r(y,z')-\nabla_{z} d_r(y,z'')\| \leq L_{d_r}'\|z^{\prime}-z^{\prime \prime}\| \quad \text{for all}\ z^{\prime}, z^{\prime \prime} \in \R^n,\notag
    \end{align}
    where $L_{d_r}:=(\sigma_{2}+1)L$ and $L_{d_r}':=(\sigma_1 + 1)r$.
    \end{lemma}

\begin{lemma}\label{lemma-dualxy}
For any $k\ge0$, we have
    \begin{equation*}
        \|y^{k+1}-y_{+}^{k}(z^{k+1})\| \leq \eta \|x^{k}-x^{k+1}\|+\sigma_1\alpha L\|z^{k+1}-z^k\|,
        \end{equation*}
where $\eta:=\alpha L \zeta$.
\end{lemma}

\begin{proof}
We compute
\begin{equation*}
% \label{iter-result2}
\begin{aligned}
\ &\|y^{k+1}-y_{+}^{k}(z^{k+1})\|\\ =\ &\|\proj_{\mathcal{Y}}(y^{k}+\alpha \nabla_{y} F(x^{k+1},y^{k}))-\proj_{\mathcal{Y}}(y^{k}+\alpha \nabla_{y} F(x_r(y^{k}, z^{k+1}),y^{k}))\|\notag \\
\leq\ &\|y^{k}+\alpha \nabla_{y} F(x^{k+1}, y^{k})-(y^{k}+\alpha \nabla_{y} F(x_r(y^{k}, z^{k+1}),  y^{k}))\|\notag \\
\leq\ & \alpha L(\|x^{k+1}-x_r(y^{k}, z^{k})\|+\|x_r(y^{k}, z^{k})-x_r(y^{k}, z^{k+1})\|) \notag \\
\leq\ & \eta\|x^{k}-x^{k+1}\|+\sigma_1\alpha L\|z^{k+1}-z^k\|,
\end{aligned}
\end{equation*}
where the first inequality is due to the nonexpansiveness of the projection operator, the second is due to the $L$-Lipschitz continuity of $\nabla_y F(\cdot,\cdot)$, and the third follows from Proposition \ref{prop:lip} and \eqref{lip-z}. The proof is complete.
\end{proof}

\begin{lemma}[Primal descent]
\label{lemma-F-des} 
For any $k\ge0$, we have
\begin{align*}
& F_r(x^{k}, y^{k},z^k)-F_r(x^{k+1}, y^{k+1},z^{k+1})\\
\ge\ &
\frac{2\lambda^{-1}+r-L}{2}\|x^k-x^{k+1}\|^2 + \langle\nabla_{y} F_r(x^{k+1}, y^{k},z^k), y^{k}-y^{k+1}\rangle-\frac{L}{2}\|y^k-y^{k+1}\|^2 \\  &  +\frac{(2-\beta)r}{2 \beta}\|z^{k}-z^{k+1}\|^{2}. 
\end{align*}
\end{lemma}

\begin{proof}
One can infer from the definition that $F_{x^k,\lambda}(\cdot,y^k)$ is $\lambda^{-1}$-strongly convex. Therefore, we have
\begin{equation*}
\begin{aligned}
F_r(x^{k}, y^{k},z^{k}) & =F(x^{k}, y^{k})+ \frac{r}{2}\|x^k-z^{k}\|^2  = F_{x^k,\lambda}(x^k,y^k) + \frac{r}{2}\|x^k-z^{k}\|^2 \\
& \ge F_{x^k,\lambda}(x^{k+1},y^k)+\frac{r}{2}\|x^{k+1}-z^{k}\|^2+\frac{\lambda^{-1}+r}{2}\|x^k-x^{k+1}\|^2.
\end{aligned}
\end{equation*}
Moreover, Fact \ref{fact-2} implies that
\begin{equation*} 
F_{x^k,\lambda}(x^{k+1},y^k)\ge F(x^{k+1},y^k) + \frac{\lambda^{-1}-L}{2}\|x^{k+1}-x^k\|^2.
\end{equation*}
It follows that
\begin{align}\label{primaldec-key1}
F_r(x^{k},y^{k}, z^k) &\ge F(x^{k+1},y^k)+\frac{r}{2}\|x^{k+1}-z^k\|^2+\frac{2\lambda^{-1}+r-L}{2}\|x^k-x^{k+1}\|^2\notag\\
&= F_r(x^{k+1},y^{k}, z^{k})+\frac{2\lambda^{-1}+r-L}{2}\|x^k-x^{k+1}\|^2.
\end{align}
Next,  as $\nabla_y F_r(x,\cdot,z)$ is $L$-Lipschitz continuous for any $x\in\mathcal{X}$ and $z\in\R^n$, we have 
    \begin{align}\label{primaldec-key2}
        F_r(x^{k+1}, y^{k},z^k)-F_r(x^{k+1}, y^{k+1},z^k) \ge \langle\nabla_{y} F_r(x^{k+1},y^{k}, z^k), y^{k}-y^{k+1}\rangle-\frac{L}{2}\|y^k-y^{k+1}\|^2.
    \end{align}
At last, based on the update $z^{k+1}=z^{k}+\beta(x^{k+1}-z^{k})$, we get
\begin{equation}\label{primaldec-key3}
F_r(x^{k+1}, y^{k+1},z^{k})-F_r(x^{k+1},y^{k+1}, z^{k+1})  = \frac{(2-\beta)r}{2 \beta}\|z^{k}-z^{k+1}\|^{2}.
\end{equation}
By summing up \eqref{primaldec-key1}, \eqref{primaldec-key2}, and \eqref{primaldec-key3}, we obtain the desired result.
\end{proof}

\begin{lemma}[Dual ascent]\label{lemma-d-aes} 
For any $k\ge0$, we have
\begin{equation*}
% \label{dual-ascent}
 \begin{aligned}
    \ & d_r(y^{k+1},z^{k+1})-d_r(y^{k},z^k)\\
    \ge\ &\langle\nabla_{y} F_r(x_r(y^{k}, z^{k}),  y^{k}, z^{k}), y^{k+1}-y^{k}\rangle-\frac{L_{d_r}}{2}\|y^{k}-y^{k+1}\|^{2}\,\\
    &+\frac{r}{2}\left\langle z^{k+1}-z^{k},z^{k+1}+z^{k}-2 x_r(y^{k+1}, z^{k+1})\right\rangle. 
    \end{aligned}
\end{equation*}
\end{lemma}

\begin{proof}
Based on Lemma \ref{lemma-dualdiff}, $\nabla_{y} d_r(\cdot,z)$ is $L_{d_r}$-Lipschitz continuous for any $z \in \mathbb{R}^n$. Thus, we have 
        \begin{align*}
        \ & d_r(y^{k+1},z^k)-d_r(y^{k},z^k)  
        \geq \langle\nabla_{y} d_r(y^{k},z^k), y^{k+1}-y^{k}\rangle-\frac{L_{d_r}}{2}\|y^{k}-y^{k+1}\|^{2} \\
        =\ & \langle \nabla_{y} F_r(x_r(y^{k}, z^{k}), y^{k}, z^{k}), y^{k+1}-y^{k}\rangle-\frac{L_{d_r}}{2}\|y^{k}-y^{k+1}\|^{2}.
        \end{align*}
In addition, one has 
        \begin{align*}
        &d_r(y^{k+1}, z^{k+1})-d_r(y^{k+1}, z^{k})\notag\\ 
        =\ & F_r(x_r(y^{k+1}, z^{k+1}), y^{k+1}, z^{k+1})-F_r(x_r(y^{k+1}, z^{k}), y^{k+1},z^{k}) \\
        \geq\ &  F_r(x_r(y^{k+1}, z^{k+1}), y^{k+1},z^{k+1})-F_r(x_r(y^{k+1}, z^{k+1}), y^{k+1},z^{k}) \\
        =\ & \frac{r}{2}\|x_r(y^{k+1}, z^{k+1})-z^{k+1}\|^{2}-\frac{r}{2}\|x_r(y^{k+1}, z^{k+1})-z^{k}\|^{2} \\
        =\ & \frac{r}{2} \left\langle z^{k+1}-z^{k},z^{k+1}+z^{k}-2 x_r(y^{k+1}, z^{k+1})\right\rangle.
        \end{align*}
Finally, by combining the above inequalities, the proof is complete.
\end{proof}

\begin{lemma}[Proximal descent (smoothness)]
\label{lemma-p-des} 
    For any $k\ge0$, we have
   \begin{equation*}
   % \label{proximal-descent}
    p_r(z^k)-p_r(z^{k+1}) \ge \frac{r}{2}\left\langle z^{k+1}-z^{k},2 x_r(y(z^{k+1}), z^{k})-z^{k}-z^{k+1}\right\rangle, 
    \end{equation*}
    where $y(z^{k+1})\in Y(z^{k+1})$.
    \end{lemma}

\begin{proof}
The proof follows closely that of Proposition \ref{prop:dual_eb_KL}. Let $\psi:\R^n\times \R^n\rightarrow\R$ be the function defined by
\[
\psi(x,z) = \max\limits_{y\in \mathcal{Y}} F_r(x,y,z)
\]
and consider arbitrary $x \in \mathcal{X}$, $y \in \mathcal{Y}$, and $z \in \mathbb{R}^n$. Again, note that  $\psi(\cdot,z)$ is $(r-L)$-strongly convex. This implies that
% for any $x\in \mathcal{X}$, we have
\begin{equation}
\label{OS-GS-better-key1}
\psi(x,z) - \psi(x^\star_r(z),z) \ge \frac{r-L}{2}\|x-x^\star_r(z)\|^2. 
\end{equation}
Moreover, 
% for any $x\in \mathcal{X}$, 
we  have
\begin{align} 
\label{OS-GS-better-key2}
&\psi(x,z)-\psi(x_r^\star(z),z) \notag\\   
\leq \  &\psi(x,z)-F_r(x_r(y_+(z),z),y_+(z),z)\notag \\
= \ & \max_{y^\prime\in \mathcal{Y}} F(x,y^\prime) + \frac{r}{2}\|x-z\|^2-F_r(x_r(y_+(z),z),y_+(z),z)\notag\\
=\,& \max_{y^\prime\in \mathcal{Y}}F(x,y^\prime)-F(x_r(y_+(z),z),y_+(z)) + \frac{r}{2}\|x-z\|^2-\frac{r}{2}\|x_r(y_+(z),z)-z\|^2,
\end{align}
where the  inequality follows from
\begin{align*}
F_r(x_r(y_+(z),z),y_+(z),z) 
=\ & \min_{x'\in\mathcal{X}}\left\{ F(x',y_+(z)) +\frac{r}{2}\|x'-z\|^2\right\} \\
\leq\ & \max_{y' \in \mathcal{Y}}\min_{x'\in\mathcal{X}}\left\{F(x',y') +\frac{r}{2}\|x'-z\|^2\right\} \\
\leq  \ & \min_{x'\in\mathcal{X}}\max_{y' \in \mathcal{Y}}\left\{F(x',y') +\frac{r}{2}\|x'-z\|^2\right\}
= \psi(x_r^\star(z),z).
\end{align*}
As \eqref{OS-GS-better-key1} and \eqref{OS-GS-better-key2} hold for any $x\in\mathcal{X}$, we obtain the intermediate relation
\begin{equation*}
% \label{OS-GS-better-key3} 
    \frac{r-L}{2}\|x_r^\star(z)-x_r(y_+(z),z)\|^2 \leq \max\limits_{y^\prime\in \mathcal{Y}} F(x_r(y_+(z),z),y^\prime) - F(x_r(y_+(z),z),y_+(z)) 
\end{equation*}
by taking $x= x_r(y_+(z),z)$.

The remaining steps of the proof are the same as those of Proposition \ref{prop:dual_eb_KL}. For brevity, we omit them here.
\end{proof}

\begin{lemma}\label{lemma-dual-bd}
For any $y \in \mathcal{Y}$ and $z\in\R^n$, we have
\begin{equation*}
% \label{dual-bd}
\|x^\star_r(z)-x_r(y_{+}(z), z)\|^{2} 
 \leq \kappa \|y-y_{+}(z)\| ,
\end{equation*}
where $\kappa:=\frac{1+ \alpha L\sigma_2+\alpha L}{\alpha(r-L)}\cdot{\rm diam}(\mathcal{Y})$.
\end{lemma}

\begin{proof}
Let $y \in \mathcal{Y}$ and $z \in \mathbb{R}^n$ be arbitrary. Recall that $y(z)$ is an arbitrary vector in $Y(z)$. By the $(r-L)$-strong convexity of $F_r(\cdot, y, z)$, we have
\begin{align}
&F_r(x_r^\star(z), y_{+}(z), z)-F_r(x_r(y_{+}(z), z), y_{+}(z), z)  \geq \frac{r-L}{2}\|x_r(y_{+}(z), z)-x^\star_r(z)\|^{2}, \notag\\
&F_r(x_r(y_{+}(z), z), y(z), z)-F_r(x_r^\star(z), y(z), z)  \geq \frac{r-L}{2}\|x_r(y_{+}(z), z)-x_r^\star(z)\|^{2}.\notag
\end{align}
 Moreover, since $(x_r^\star(z),y(z))$ is a saddle point of the convex-concave function $F_r(\cdot,\cdot,z)$ \citep{sion1958general}, we have $F_r(x_r^\star(z), y(z), z) \geq F_r(x_r^\star(z), y_{+}(z), z)$, which implies that
\begin{equation}\label{dualbd-strcvx}
F_r(x_r(y_{+}(z), z), y(z), z)-F_r(x_r(y_{+}(z), z), y_{+}(z), z) \geq  (r-L)\|x_r(y_{+}(z), z)-x_r^\star(z)\|^{2}.
\end{equation}
Note that $y_{+}(z)$ is the maximizer of 
\[
\max_{y' \in \mathcal{Y}}\big\langle y+\alpha \nabla_{y} F_r(x_r(y, z), y, z)-y_{+}(z) , y'\big\rangle.
\]
For simplicity, we define the function $\xi: \mathbb{R}^d \rightarrow \mathbb{R}$ by
\begin{align*}
\xi(\cdot)
:=\ &\alpha F_r(x_r(y_{+}(z), z),\cdot, z)-\big\langle \alpha\nabla_{y} F_r(x_r(y_{+}(z), z), y_{+}(z), z),\cdot\big\rangle \\ \ &-\big\langle y_{+}(z)-y-\alpha \nabla_{y} F_r(x_r(y, z), y, z), \cdot\big\rangle.
\end{align*}
Then, we have
\begin{align*}
\max_{y' \in \mathcal{Y}}\ \xi(y')
&\leq \alpha F_r(x_r(y_{+}(z), z),y_+(z), z)-\big\langle\alpha\nabla_y F_r(x_r(y_{+}(z), z),y_+(z), z), y_+(z)\big\rangle\, \notag\\
&\quad + \max_{y' \in \mathcal{Y}} \big\langle y+\alpha \nabla_{y} F_r(x_r(y, z), y, z)-y_{+}(z), y'\big\rangle \notag\\
&\leq \xi(y_{+}(z)),
\end{align*}
where the first inequality holds because $F_r(x_r(y_{+}(z), z),\cdot,z)$ is concave. Therefore, we have $\xi(y(z))\leq \xi(y_{+}(z))$, which implies that
\begin{align}\label{dualbd-key}
&F_r(x_r(y_{+}(z), z), y(z), z)-F_r(x_r(y_{+}(z), z), y_{+}(z), z) \notag\\
\leq &\ \frac{1}{\alpha}\Big\langle y(z)-y_{+}(z), \alpha\nabla_{y} F_r(x_r(y_{+}(z), z), y_{+}(z), z)-\alpha \nabla_{y} F_r(x_r(y, z), y, z)\Big\rangle \notag \\ \ & \ + \frac{1}{\alpha}\Big\langle y(z)-y_{+}(z), y_{+}(z)-y\Big\rangle \notag\\
\leq &\ L \|y_{+}(z)-y(z)\|(\|x_r(y_{+}(z), z)-x_r(y, z)\|+ \|y_{+}(z)-y\|)  + \frac{1}{\alpha}\|y_{+}(z)-y(z)\|\cdot \|y-y_{+}(z)\|\notag\\
\leq &\ \left(\frac{1}{\alpha}+L\sigma_2+L\right)\|y_{+}(z)-y(z)\| \cdot\|y-y_{+}(z)\|.
\end{align}
Here, the second inequality is due to the $L$-Lipschitz continuity of $\nabla_y F_r(\cdot,\cdot,z)$ and the last inequality is from \eqref{lip-y}.
Hence, by combining \eqref{dualbd-strcvx} and \eqref{dualbd-key}, we obtain
\[
(r-L)\|x_r^\star(z)-x_r(y_{+}(z), z)\|^{2}\leq \left(\frac{1}{\alpha}+ L\sigma_2+L\right){\rm diam}(\mathcal{Y})\cdot\|y-y_{+}(z)\|,
\]
which proves the desired result.
\end{proof}

