\ge\ & 14r\beta\|x_r(y(z^{k+1}),z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|^{2}.
\end{align*}

\textbf{Scenario (1)}. For the case where the K{\L} exponent $\theta \in (\tfrac{1}{2},1)$, we deduce from Proposition \ref{prop:dual_eb_KL}(b) that 
\begin{align*}
    \|y^{k}-y_{+}^{k}(z^{k+1})\|^2  & \leq 224r\alpha\beta\|x_r(y(z^{k+1}),z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|^{2}  \\ &\leq  224r\alpha\beta \omega_2^2 \|y^{k}-y_{+}^{k}(z^{k+1})\|^{\frac{1}{\theta}},  
\end{align*}
which gives $\|y^{k}-y_{+}^{k}(z^{k+1})\|\leq \rho_1\beta^{\frac{\theta}{2\theta-1}}$ with $\rho_1 := (224r\alpha\omega_2^2)^{\frac{\theta}{2\theta-1}}$. Additionally, using the update $z^{k+1} = z^k + \beta( x^{k+1} - z^k )$ and Proposition \ref{prop:dual_eb_KL}(b), we have
\begin{align*}
\|x^{k+1}-z^{k}\|^{2}  \ & =\frac{1}{\beta^2}\|z^{k+1}-z^{k}\|^{2}\\
