    \|\nabla_{z} d_r(y,z')-\nabla_{z} d_r(y,z'')\|=\ &r\|z'-x_r(y,z')-(z''-x_r(y,z''))\| \\
    \leq\ & r\|z^{\prime}-z^{\prime \prime}\|+r\|x_r(y, z')-x_r(y, z'')\| \\
