\begin{proof}
One can infer from the definition that $F_{x^k,\lambda}(\cdot,y^k)$ is $\lambda^{-1}$-strongly convex. Therefore, we have
\begin{equation*}
\begin{aligned}
F_r(x^{k}, y^{k},z^{k}) & =F(x^{k}, y^{k})+ \frac{r}{2}\|x^k-z^{k}\|^2  = F_{x^k,\lambda}(x^k,y^k) + \frac{r}{2}\|x^k-z^{k}\|^2 \\
& \ge F_{x^k,\lambda}(x^{k+1},y^k)+\frac{r}{2}\|x^{k+1}-z^{k}\|^2+\frac{\lambda^{-1}+r}{2}\|x^k-x^{k+1}\|^2.
\end{aligned}
\end{equation*}
Moreover, Fact \ref{fact-2} implies that
\begin{equation*} 
F_{x^k,\lambda}(x^{k+1},y^k)\ge F(x^{k+1},y^k) + \frac{\lambda^{-1}-L}{2}\|x^{k+1}-x^k\|^2.
\end{equation*}
It follows that
\begin{align}\label{primaldec-key1}
F_r(x^{k},y^{k}, z^k) &\ge F(x^{k+1},y^k)+\frac{r}{2}\|x^{k+1}-z^k\|^2+\frac{2\lambda^{-1}+r-L}{2}\|x^k-x^{k+1}\|^2\notag\\
&= F_r(x^{k+1},y^{k}, z^{k})+\frac{2\lambda^{-1}+r-L}{2}\|x^k-x^{k+1}\|^2.
\end{align}

Next,  as $\nabla_y F_r(x,\cdot,z)$ is $L$-Lipschitz continuous for any $x\in\mathcal{X}$ and $z\in\R^n$, we have 
    \begin{align}\label{primaldec-key2}
        F_r(x^{k+1}, y^{k},z^k)-F_r(x^{k+1}, y^{k+1},z^k) \ge \langle\nabla_{y} F_r(x^{k+1},y^{k}, z^k), y^{k}-y^{k+1}\rangle-\frac{L}{2}\|y^k-y^{k+1}\|^2.
    \end{align}

At last, based on the update $z^{k+1}=z^{k}+\beta(x^{k+1}-z^{k})$, we get
\begin{equation}\label{primaldec-key3}
F_r(x^{k+1}, y^{k+1},z^{k})-F_r(x^{k+1},y^{k+1}, z^{k+1})  = \frac{(2-\beta)r}{2 \beta}\|z^{k}-z^{k+1}\|^{2}.
\end{equation}
By summing up \eqref{primaldec-key1}, \eqref{primaldec-key2}, and \eqref{primaldec-key3}, we obtain the desired result.
\end{proof}

