we see that 
% for any $x\in \mathcal{X}$, 
\begin{equation}
\label{eq:dual1}
\psi(x,z) - \psi(x_r(y(z),z),z) \ge \frac{r-L}{2}\|x-x_r(y(z),z)\|^2. 
\end{equation}

In addition, we have
\begin{align} 
\label{eq:dual2}
&\psi(x,z) - \psi(x_r(y(z),z),z)\notag\\   
\leq \  &\psi(x,z)-F_r(x_r(y_+(z),z),y_+(z),z)\notag \\
\leq \ & \max_{y^\prime\in \mathcal{Y}} F(x,y^\prime) + \frac{r}{2}\|x-z\|^2-F_r(x_r(y_+(z),z),y_+(z),z)\notag\\
=\,& \max_{y^\prime\in \mathcal{Y}}F(x,y^\prime)-F(x_r(y_+(z),z),y_+(z)) + \frac{r}{2}\|x-z\|^2-\frac{r}{2}\|x_r(y_+(z),z)-z\|^2,
\end{align}
where the first inequality follows from
\begin{align*}
F_r(x_r(y_+(z),z),y_+(z),z) 
=\ & \min_{x'\in\mathcal{X}}\left\{ F(x',y_+(z)) +\frac{r}{2}\|x'-z\|^2\right\} \nonumber \\
\leq\ & \max_{y' \in \mathcal{Y}}\min_{x'\in\mathcal{X}}\left\{F(x',y') +\frac{r}{2}\|x'-z\|^2\right\} \nonumber \\
=\ & \min_{x'\in\mathcal{X}}\left\{F(x',y(z)) +\frac{r}{2}\|x'-z\|^2\right\} \nonumber \\
=\ & \min_{x'\in\mathcal{X}} \psi(x',z)
= \psi(x_r(y(z),z),z). % \label{eq:Fr-one}
\end{align*}

% \Jiajin{We may have to double-check the above derivation. --- confirmed. With the uniform KL property, we can confirm  $x(y(z),z)$ is unique over $Y(z)$.}
