\begin{equation}\label{OS-GS-better-key3-main} 
% \begin{aligned}
     \frac{r-L}{2}\|x_r(y(z),z)-x_r(y_+(z),z)\|^2\leq  \max\limits_{y^\prime\in \mathcal{Y}} F(x_r(y_+(z),z),y^\prime) - F(x_r(y_+(z),z),y_+(z)) 
% \end{aligned}
\end{equation}
by taking $x= x_r(y_+(z),z)$.

Now, we utilize the K{\L} exponent $\theta$ of the dual problem to bound the right-hand side of 
\eqref{OS-GS-better-key3-main}  in terms of $\|y-y_+(z)\|$. Consider the following two cases:

\item If $\theta \in (0,1)$, then we have
\begin{align*}
% \label{KL-key-01}
& \mu\left(\max\limits_{y^\prime\in \mathcal{Y}} F(x_r(y_+(z),z),y^\prime) - F(x_r(y_+(z),z),y_+(z))\right)^{\theta}\notag\\
\leq \ & \dist(0, -\nabla_y F(x_r(y_+(z),z),y_+(z))+\partial\iota_{\mathcal{Y}}(y_+(z))) \notag\\ 
\leq \ & \dist(0, -\nabla_y F(x_r(y,z),y_+(z)) +\partial\iota_{\mathcal{Y}}(y_+(z)))   \notag\\
\ & + \|\nabla_y F(x_r(y,z),y_+(z))-\nabla_y F(x_r(y_+(z),z),y_+(z))\|\notag\\ 
