Lastly, we have
\begin{align*}
    \|x^{k+1}-x^k\|^2 \ & \leq {\frac{224}{3}r\beta\lambda}\|x_r(y(z^{k+1}),z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|^{2} \\
   \  &\leq {\frac{224}{3}r\omega^2_2\beta\lambda}\|y^{k}-y_{+}^{k}(z^{k+1})\|^{\frac{1}{\theta}} \leq \rho_3^2 \beta^{\frac{2\theta}{2\theta-1}},  
\end{align*}
where $\rho_3 := \sqrt{{\frac{224}{3}r\omega_2^2\lambda}\rho_1^{\frac{1}{\theta}}}$.

Combining the above inequalities, we have
\begin{align*}
& \max \left\{\|x^{k}-x^{k+1}\|,\|y^{k}-y_{+}^{k}(z^{k+1})\|,\|z^{k}-x^{k+1}\|\right\} \leq  \max\left\{ \rho_1\beta^{\frac{\theta}{2\theta-1}}, \rho_2\beta^{\frac{1}{4\theta-2}}, \rho_3 \beta^{\frac{\theta}{2\theta-1}}\right\}. 
\end{align*}
It then follows from Lemma \ref{lemma-episolcol}
 that $\left(x^{k+1}, y^{k+1}\right)$ is a $\rho\cdot\max\{ \rho_1\beta^{{\theta}/{(2\theta-1)}},$ $ \rho_2\beta^{1/{(4\theta-2)}}, \rho_3\beta^{{\theta}/{(2\theta-1)}}\}$-GS of problem \eqref{eq:problem}. 

 For the concave case, we can replace the primal-dual quantity $x_r( y(z^{k+1}), z^{k+1} )$ by the primal quantity $x_r^\star( z^{k+1} )$ on the right-hand side of the inequality for Scenario (1) and apply Lemma \ref{lemma-dual-bd} in Appendix \ref{sec:dual} (so that $\theta$ and $\omega_2$ are replaced by $1$ and $\kappa = \tfrac{1 + \alpha L \sigma_2 + \alpha L}{\alpha (r-L)} \cdot \textrm{diam}(\mathcal{Y})$, respectively) to conclude that $\left(x^{k+1}, y^{k+1}\right)$ is a $\max\{ \rho_1\beta, \rho_2\beta^{1/2}, \rho_3 \beta\}$-GS of problem \eqref{eq:problem}.




Furthermore, observe that for the case where $\theta \in (\tfrac{1}{2}, 1)$, the optimization-stationarity measure of $z^{k+1}$ satisfies
\begin{equation}
\label{eq:os-gs}
\begin{aligned}
    & \|z^{k+1}-x_r^\star(z^{k+1})\| \\
    \leq\ &  \|z^{k+1}-x^{k+1}\|+\| x^{k+1} - x_r(y^k,z^k) \| + \| x_r(y^k,z^k) - x_r(y^k,z^{k+1}) \|\\
    \ & + \|x_r(y^k,z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|+ \|x_r(y_{+}^{k}(z^{k+1}), z^{k+1})-x_r^\star(z^{k+1})\|\\
     \leq\ &  (1+\sigma_1)\|z^{k}-x^{k+1}\| + \zeta\|x^{k}-x^{k+1}\| + \sigma_2 \|y^k-y_{+}^{k}(z^{k+1})\|+ \omega_2 \|y^k-y_{+}^{k}(z^{k+1})\|^{\frac{1}{2\theta}} \\
    \leq\ & \max\left\{\left(\rho_2(1+\sigma_1)+ \omega_2 \rho_1^\frac{1}{2\theta}\right)\beta^{\frac{1}{4\theta-2}},(\zeta\rho_3+\sigma_2\rho_1) \beta^{\frac{\theta}{2\theta-1}} \right\}, 
\end{aligned}
\end{equation}
where the second inequality follows from the update $z^{k+1} = z^k + \beta (x^{k+1} - z^k)$, Proposition \ref{prop:lip}, Corollary \ref{prop:dual_eb_KL2}, Lemma \ref{lemma-sollip}, and the fact that $0 < \beta \le \tfrac{1}{28}$.
It is evident that the dependence on $\beta$ is identical to that of the game-stationarity measure of $(x^{k+1}, y^{k+1})$.
For the concave case, the optimization-stationarity measure of $z^{k+1}$ can be bounded similarly.

\textbf{Scenario (2)}. Proposition \ref{prop:decrease} implies that for any $k \in\{0,1, \ldots, K-1\}$, we have 
\begin{align}
\label{eq:suff-decrease}
\Phi_r^k-\Phi_r^{k+1} 
\ge \frac{3}{16\lambda}\|x^{k}-x^{k+1}\|^{2}+\frac{1}{16\alpha}\|y^{k}-y_{+}^{k}(z^{k+1})\|^2 +\frac{2r}{7\beta}\|z^{k}-z^{k+1}\|^{2}.
\end{align}

Next, let us consider case (c). First, suppose that the K{\L} exponent $\theta \in (0, \tfrac{1}{2}]$. 
Once again, we can use Proposition \ref{prop:decrease} to obtain 
\begin{align*}
\Phi_r^k-\Phi_r^{k+1} 
\ge\ &  \frac{3}{8\lambda}\|x^{k}-x^{k+1}\|^{2}+\frac{1}{8\alpha}\|y^{k}-y_{+}^{k}(z^{k+1})\|^2 +\frac{4r}{7\beta}\|z^{k}-z^{k+1}\|^{2}\\
\ & -14r\beta\|x_r(y(z^{k+1}),z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|^{2}.
\end{align*}

Using Proposition \ref{prop:dual_eb_KL}(b) and the boundedness of $\mathcal{Y}$, we have
% there exists  for each $\theta \in(0,\frac{1}{2})$ that 
\begin{equation}\label{dual-eb-bd}
\begin{aligned}
  \|x_r(y(z^{k+1}),z^{k+1})-x_r(y_{+}^{k}(z^{k+1}), z^{k+1})\|
&\leq \omega_2 \|y^{k}-y_{+}^{k}(z^{k+1})\|^{\frac{1}{2\theta}}\\
&=  \omega_2 \|y^{k}-y_{+}^{k}(z^{k+1})\|^{\frac{1}{2\theta}-1} \|y^{k}-y_{+}^{k}(z^{k+1})\|\\
&\leq   \omega_2\cdot {\rm diam}(\mathcal{Y})^{\frac{1}{2\theta}-1}\cdot \|y^{k}-y_{+}^{k}(z^{k+1})\|.
\end{aligned}
\end{equation}

It follows that
\begin{align*}
\Phi_r^k-\Phi_r^{k+1} 
\ge \ &  \frac{3}{8\lambda}\|x^{k}-x^{k+1}\|^{2}+\left(\frac{1}{8\alpha}-14r\beta\omega_2^2\cdot{\rm diam}(\mathcal{Y})^{\frac{1-2\theta}{\theta}}\right) \|y^{k}-y_{+}^{k}(z^{k+1})\|^2  +\frac{4r}{7\beta}\|z^{k}-z^{k+1}\|^{2}.
\end{align*}
Since 
$\beta  \leq \frac{ {\rm diam}(\mathcal{Y})^{\frac{2\theta-1}{\theta}}}{224 \alpha r\omega_2^2}$, we have 
\begin{align*}
&\Phi_r^k-\Phi_r^{k+1} \ge  \frac{3}{8\lambda}\|x^{k}-x^{k+1}\|^{2}+\frac{1}{16\alpha}\|y^{k}-y_{+}^{k}(z^{k+1})\|^2 +\frac{4r}{7\beta}\|z^{k}-z^{k+1}\|^{2}.
\end{align*}
The desired result can then be obtained by following a similar argument as that in the paragraph proceeding \eqref{eq:suff-decrease}.

When the K{\L} exponent $\theta=0$, we can apply Proposition \ref{prop:dual_eb_KL}(a) to derive the inequality \eqref{dual-eb-bd} 
% by letting $\theta=\frac{1}{2}$ and replacing $\omega_2$ with $\omega_1$. 
with $\theta$ and $\omega_2$ being replaced by $\tfrac{1}{2}$ and $\omega_1$, respectively.
The desired result then follows by adapting the argument in the preceding paragraph.
\end{proof}
